INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metroid Dread', 'Join intergalactic bounty hunter Samus Aran in her first new 2D Metroid story in 19 years. Samus’ story continues after the events of the Metroid Fusion game when she descends upon planet ZDR to investigate a mysterious transmission sent to the Galactic Federation. The remote planet has become overrun by vicious alien lifeforms and chilling mechanical menaces. Samus is more agile and capable than ever, but can she overcome the inhuman threat stalking the depths of ZDR?' FROM games WHERE igdb_id = 15698 ON CONFLICT (game_id, language_code) DO NOTHING;
