INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('runes-of-avalon-2', 87067, '2021-08-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3yr0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arz24.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Runes of Avalon 2', 'Take a fantastic journey through a magical world as you match the runes to help Evelyne fulfil her mission and find her way home. Welcome to the once glorious empire of Avalon, now clouded by the darkness of the evil Morganna''s spells. After defeating Morganna in an intense magical battle, Evelyne, the protector of Avalon, must now cleanse Avalon from the dark curse with her Rune Magic. Help Evelyne to complete her mission and find her way home by matching the runes, encountering new locations, new spells and new challenges along the way. With three game modes and some unexpected twists, Runes of Avalon 2 takes you to an enchanting world of magic and mystery you won''t want to leave. Runes of Avalon 2 is a puzzle game with a twist, match-3 mechanic that you have yet to see. *** Features: *** - 100 great levels - Amulet of Spells with 4 new spells - 6 power-ups - 10 new enchanting images to reveal - Three game modes: Quest, Endless and Time Attack - JigSaw mini-game - Mystic music & sound effects and more... *** Discover more from Anawiki Games! *** - The Perfect Tree - Avalon Legends Solitaire HD - Arizona Rose and the Pirates'' Riddles HD - Dress-Up Pups HD You can always find an updated list at www.anawiki.com!' FROM games WHERE igdb_id = 87067 ON CONFLICT (game_id, language_code) DO NOTHING;
