INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Country Discoverer', 'Arcade style twin-stick shooter with a robust rank system and leaderboards. Test your reflexes and your intellect as you sail the seas discovering new countries by launching giant telescopes at them as they hurtle towards you. Don''t worry about it - it''s weird.' FROM games WHERE igdb_id = 144842 ON CONFLICT (game_id, language_code) DO NOTHING;
