INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Magbot', 'Super Magbot is a precision platformer with no jumping! Players will have to traverse four distinct worlds with new mechanics and challenges unlocking along the way. Learn how to use Super Magbot''s magnetic powers and use the different magnets to beat more than 150 levels. Enjoy unique challenging mechanics with classic 16-bit gaming vibes.' FROM games WHERE igdb_id = 132921 ON CONFLICT (game_id, language_code) DO NOTHING;
