INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('smelter', 119191, '2021-04-21', 69, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2he0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arb0p.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smelter', 'Smelter is a real time strategy-action platformer hybrid inspired by classic games of the 16-bit era. Players play as Eve, who teams up with the mysterious armor, Smelter, in her search for Adam. Expand Smelter’s fortifications throughout the various domains of the Rumbly Lands watched over by the Guardians and Watchers. Defend against onslaughts of enemies, discover lost ruins, meet new and eccentric characters and grow stronger before diving into pulse pounding, 2D side-scrolling action platformer levels. - Combines the methodical planning of real time strategy games with the energy of action platformers. - Bespoke handcrafted pixel art - Three different Elemental skill sets, each with their own unique movement, attack and defense skills you’ll need to fight monsters, traverse levels, and solve puzzles. - Three unique Domains with their own memorable stories, stages, side characters, enemies and bosses' FROM games WHERE igdb_id = 119191 ON CONFLICT (game_id, language_code) DO NOTHING;
