INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'In Rays of the Light', 'There is only you, the abandoned remains of a former life and the flourishing nature that feels great in the absence of man. This world is both gloomy and empty, but so incredibly beautiful. “In rays of the Light” is an atmospheric author’s parable about our place in this world, life and death. Explore a mysterious territory filled with a variety of details that reveal the story. Solve logic puzzles and study text messages along the way.' FROM games WHERE igdb_id = 144416 ON CONFLICT (game_id, language_code) DO NOTHING;
