INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taxi Chaos', 'Taxi Chaos is a casual arcade racing game where you select one of a wide range of unlockable cabs, each of whom has different attributes: the strong muscle car, the superfast exotic supercar, the corner-drifting Japanese tuner, an American classic from the ''60s and more: Taxi Mayhem has them all. Your goal is to try and earn big cab fares, by picking up any customers and dropping them off at their destination spots as fast as possible before you run out of time! However, beware: most customers are a little crazy.' FROM games WHERE igdb_id = 140701 ON CONFLICT (game_id, language_code) DO NOTHING;
