INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ari In Wonderland: Episode 1', 'Ari after a long day falls fast asleep and goes back into wonderland. She has no idea why she is back. A lot has changed and the more she thinks about her past it gets more and more blurry. Ari meets some friends on the way to help her find what she wants and to restore wonderland, discover Ari''s past along with her.' FROM games WHERE igdb_id = 200646 ON CONFLICT (game_id, language_code) DO NOTHING;
