INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fracked', 'From the creators of Phantom: Covert Ops, Fracked is the trailblazing new VR action adventure that collides relentless gunfights with free running, skiing, and climbing. Stranded in a remote mountain facility, you play as a reluctant hero forced into a final stand between the planet and a legion of interdimensional enemies. Take aim and run head-first into the action as you shoot, ski, and climb your way across an extreme adventure. Uncompromised, audacious, and stylish, Fracked grabs PS VR by the Moves and delivers an ass kicking VR game enhanced for PS5.' FROM games WHERE igdb_id = 145451 ON CONFLICT (game_id, language_code) DO NOTHING;
