INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney Magical World 2: Enchanted Edition', 'Immerse yourself in a world of magic in Disney Magical World 2: Enchanted Edition! Make a new home in this enchanted Disney world and hang out with beloved Disney characters! Explore Disney-themed worlds full of fun challenges and live your dream life as you go on fun adventures, dance with Disney Princesses, soar with Mickey in Magical Dream parades, and more! Get ready for hours of enchanted fun as you build your own Disney Magical World!' FROM games WHERE igdb_id = 172428 ON CONFLICT (game_id, language_code) DO NOTHING;
