INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('clockwork-aquario', 141317, '2021-11-30', 78, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2t5x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8rd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clockwork Aquario', 'Clockwork Aquario was the last arcade game ever developed by the legendary Westone Bit Entertainment in 1992, but was never finished. The game was thought to be lost in time, but Strictly Limited Games set out on the mission to dig deep into video game archeology and save Clockwork Aquario from being lost in time. Beautiful pixel art and vibrant colors with three unique characters: Huck Londo, the daring ghost hunter, Elle Moon, the brave adventuress and Gush, the warmhearted giant robot.' FROM games WHERE igdb_id = 141317 ON CONFLICT (game_id, language_code) DO NOTHING;
