INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Five Nights at Freddy''s: Security Breach', 'Five Nights at Freddy’s: Security Breach is the latest installment of the family-friendly horror games loved by millions of players from all over the globe. Play as Gregory, a young boy trapped overnight in Freddy Fazbear''s Mega Pizzaplex. With the help of Freddy Fazbear himself, Gregory must survive the near-unstoppable hunt of reimagined Five Nights at Freddy’s characters, as well as new, horrific threats.' FROM games WHERE igdb_id = 138933 ON CONFLICT (game_id, language_code) DO NOTHING;
