INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jupiter Hell', 'Jupiter Hell is a classic turn-based roguelike set in a 90''s flavored sci-fi universe. Rip and tear zombies, demons and unmentionable monstrosities, using shotguns, chainguns and the trusty chainsaw, to the shine of CRT monitors and the tune of heavy metal!' FROM games WHERE igdb_id = 25825 ON CONFLICT (game_id, language_code) DO NOTHING;
