INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vertical Shift', 'A VR Esport unlike any other. Fly through the arenas equipped with your Zenith Suit, an advanced movement system. Your Zenith Suit is equipped with Grapple Hooks, Jet Packs, and Gliders, giving you ultimate control over your flight. Vertical Shift also features a single-player campaign! Explore the City of Orion, a futuristic metropolis on the brink of collapse. Join the resistance and help take down the evil government through a variety of missions and activities. Or just swing around and take in the sights!' FROM games WHERE igdb_id = 144475 ON CONFLICT (game_id, language_code) DO NOTHING;
