INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('not-a-happy-family', 143342, '2021-02-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2skh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9183.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Not a Happy Family', 'Not a Happy Family is a game that you play as a blind protagonist. Your role in story mode is to explore the entire house for clues to understand your family''s history. The plot was written in a way that leaves several things in suspense, counted between the lines, leaving the player always with "a flea behind the ear" related to the events of the game. It was also used a device for the player to set the story of the game without knowing that he is taking an important action, that is, it is possible to replay more than once and obtain different outcomes for each day and for the game itself. The "For Fun" mode is the way in which the player must try to escape from the mansion while having a monster behind him wanting to kill him. It is a way that can make the player tense for not knowing where the monster is and even more, for the aggravating player being blind.' FROM games WHERE igdb_id = 143342 ON CONFLICT (game_id, language_code) DO NOTHING;
