INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-crypto-prophecies', 186005, '2021-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4b3f.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Crypto Prophecies', 'A MAGICAL SHOWDOWN Enter the Crypto Kingdom of Opulentos and put your crypto prophecy to the test. Go head-to-head with other players in this zero-sum price prediction game. Place your wager and cast your magic against your opponent as you foresee the crypto futures to make your profits. Use NFT Crypto Prophets to battle against other players. Predict where the candles will move next. In 10 fast paced rounds use your Crypto Prophet to predict how each 10 second candle will close to beat your opponent. The player with the most points will take all the winnings. Also benefit from many game features where players are rewarded with daily & weekly league table prizes and prize draws by playing to earn entry tickets and climbing leaderboards.' FROM games WHERE igdb_id = 186005 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 186005 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
