INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('prison-tycoon-under-new-management', 152405, '2021-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3a2o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar11df.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prison Tycoon: Under New Management', 'Design, build and run your own prison! Plan and build your own prison from the ground up! Secure government grants, hire guards and staff and begin welcoming new prisoners in this reboot of the Prison Tycoon franchise. The goal of a good Warden is not to punish their prisoners, it’s to rehabilitate them into productive members of society. In Under New Management, each inmate must work through their own issues that landed them in prison, and it’s your job to provide them with the help they need to get healthy. “Prison Tycoon : Under New Management” is looking for a good Warden. Are you up for the job?' FROM games WHERE igdb_id = 152405 ON CONFLICT (game_id, language_code) DO NOTHING;
