INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sir Lovelot', 'Sir Lovelot is on a quest to find the love of his life, and only you can help him avoid the cold sting of loneliness (but let’s be real: solitude is great!). Join him in a wacky precision platformer in which he’ll realize that finding love isn’t as easy as he thinks! Collects gifts, avoid treacherous hazards and fight off weird creatures, all in the best possible time! It''s an absolutely heartbreaking hairy-tale, if ever there was one...' FROM games WHERE igdb_id = 132982 ON CONFLICT (game_id, language_code) DO NOTHING;
