INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rotund Takeoff', 'You are Chubbit, a plump bunny plunged into a precision platforming nightmare! To escape, simply move left, move right, and master the nuanced dynamics of ceaseless bouncing! Playing well means playing fast, exemplified by the simple stopwatch HUD. Earn gold medals through speed and strategy to open map shortcuts and bonus levels as you journey across vibrant worlds toward the light of home!' FROM games WHERE igdb_id = 139303 ON CONFLICT (game_id, language_code) DO NOTHING;
