INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wonder Boy: Asha in Monster World', 'Asha, the warrior protagonist of the game, is involved in a serious incident that will affect the survival of her world. Our green-haired heroine doesn’t have to save the world all alone, and sets off on an adventure with her cute flying friend, the blue Pepelogoo. Asha and the Pepelogoo have to work together to become the heroes the world needs them to be. The road ahead is long - will they be able to save their world?' FROM games WHERE igdb_id = 137048 ON CONFLICT (game_id, language_code) DO NOTHING;
