INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rocket-league-sideswipe', 144983, '2021-11-15', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7nk6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar15rg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocket League Sideswipe', 'Car games and soccer collide in Rocket League Sideswipe! Multiplayer car soccer has been reimagined for mobile devices by the makers of the hit game Rocket League. Score goals in fast-paced 2-minute games and customize cars in the Garage. Party up with friends or play online games with players around the world. Drive supersonic race cars and hit the soccer ball into your opponent’s net to win matches. Already a Rocket League pro? Fly into the air and pull off trick shots, even a flip reset! Dominate the soccer field and race to the top of the car soccer leaderboard by participating in worldwide Ranked Matches. Just want to relax and have fun? Online car soccer in Casual Mode lets you perform your craziest maneuvers without affecting your rank. Multiplayer soccer games level up with a combination of action-packed soccer and rocket-powered cars. Play online multiplayer games for free and master the game’s intuitive touch controls, perfectly designed for mobile car battle gameplay. Unlock exciting Rocket Pass Cars and Items by playing online and proving yourself in the Arena. Experience online car game action from anywhere with Rocket League Sideswipe. Play together with friends and become a car soccer hero. Good luck, have fun!' FROM games WHERE igdb_id = 144983 ON CONFLICT (game_id, language_code) DO NOTHING;
