INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fights in Tight Spaces', 'Fights in Tight Spaces blends deck-building, turn-based tactics, and thrilling animated fight sequences in classic action-movie settings. Learn to balance your hand, momentum, and positioning to overcome the odds to defeat your adversaries. Pick from over 150 cards as you build a deck to suit your play style and your opponents’. Encounter random events, acquire enhancements (or injuries), and make critical choices about how best to upgrade your agent for the fights ahead.' FROM games WHERE igdb_id = 132422 ON CONFLICT (game_id, language_code) DO NOTHING;
