INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallow', 'Isabelline Fallow lived with her sisters in an isolated corner of a world that had begun to forget itself. Soon, it forgot her sisters as well. Now Isabelline walks in her sleep, every morning a new road home, every morning that home a little different than she remembers it. In her dreams, a shadow twists in agony through the smoke-steeped orange sky. With 80+ hand-drawn pixel art backgrounds, explore and solve puzzles across 3 main areas and a hub world, as well as various dreamscapes and secret locations.' FROM games WHERE igdb_id = 56437 ON CONFLICT (game_id, language_code) DO NOTHING;
