INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('paralily', 126258, '2021-11-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2n6m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arixj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ParaLily', 'ParaLily is one little girl’s adventure to retrieve her dear stuffed dinosaur Patches, who in the middle of the night sprung to life and took off through a mysterious door. This strange journey will take Lily through a set of dangerous and terrifying parallel universes, as she attempts to retrieve her little stuffed runaway. Lily can shift between the parallel universes at will; which will help her avoid danger, and solve puzzles while traversing the paranormal universes. Each universe has is its own space with unique themes, enemies, and attributes. A single level cannot be traversed by only interacting with one universe, so the relative spatial relationship of each universe is critical to gameplay. When Lily changes universes her momentum carries with her, allowing her to continue a jump from one universe to the next. This combination of parallaxing parallel universes, and momentum; creates a special blend of precision and puzzle platforming, that makes ParaLily both challenging and thoughtful. Help Lily survive the paranormal and rescue a friend, on her strange journey through a series of parallel universes, in this special blend of precision and puzzle platforming. Avoid horrifying enemies, collect magical glyphs, and discover the connection between Lily and the parallel universes.' FROM games WHERE igdb_id = 126258 ON CONFLICT (game_id, language_code) DO NOTHING;
