INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demon Slayer: Kimetsu no Yaiba - The Hinokami Chronicles', 'Become the blade that destroys demons! In Solo Mode, follow Tanjiro through the story from the Demon Slayer: Kimetsu no Yaiba anime as he faces demons in order to turn his sister Nezuko, who has become a demon, back into a human. In Versus Mode, characters from the anime, including Tanjiro and Nezuko, can be freely matched against each another in a one-versus-one setting with up to two players online or offline! Enjoy this simple but exhilarating battle system, and become the greatest demon slayer you can!' FROM games WHERE igdb_id = 153054 ON CONFLICT (game_id, language_code) DO NOTHING;
