INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armed Emeth', 'Valess, a boy earning petty cash in a commune of drifters is suddenly met by Lock, a stand-alone golem. Valess'' mother was kidnapped by a terrorist organization, and upon discovering that the leader of that organization has an enormous bounty on his head, Valess receives a golem of his own from Lock and decides to join him on an adventure into the unknown where numerous bounties await. Thus begins their journey of grit and oil across several continents!' FROM games WHERE igdb_id = 153748 ON CONFLICT (game_id, language_code) DO NOTHING;
