INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Returnal', 'Returnal is a 2021 roguelike third-person shooter video game developed by Housemarque and published by Sony Interactive Entertainment. It follows Selene Vassos, an astronaut who lands on the planet Atropos in search of the mysterious "White Shadow" signal and finds herself trapped in a time loop. After crash-landing on a shape-shifting alien planet, Selene finds herself fighting tooth and nail for survival. Every time she’s defeated, the player is forced to restart the journey.' FROM games WHERE igdb_id = 134584 ON CONFLICT (game_id, language_code) DO NOTHING;
