INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Balan Wonderworld', 'Balan Wonderworld is a wondrous action-platformer game themed around a mysterious musical theatre. The stars of the show will use special abilities from a multitude of characterful costumes as they adventure in the bizarre and imaginary land of Wonderworld. Here memories and vistas from the real world mix with the things that people hold dear. Twelve different tales await our stars in Wonderworld, each with their own unique quirks. They will explore all corners of these labyrinthine stages, using all the tricks and gimmicks hidden along the way, to get to the heart of each touching story.' FROM games WHERE igdb_id = 135992 ON CONFLICT (game_id, language_code) DO NOTHING;
