INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quantum League', 'Quantum League is the first competitive arena shooter that injects a unique time travel mechanic into the tactical way you play the game. When the timer runs out, a ''time loop'' feature revives & rewinds you, but THIS time, you get to team up with your own clones with paradoxical results!' FROM games WHERE igdb_id = 118789 ON CONFLICT (game_id, language_code) DO NOTHING;
