INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ralf''s Adventure: Aztec Mystery', 'In this retro-styled game, you will navigate labyrinthine temples, finding relics that will prove critical to solving the ancient puzzles. As with any ancient temple, there are traps aplenty, and you must keep your wits about if you wish to have any hope of finding your Mother! Descend through 8 different temples, fighting Guardians, and collecting their golden idols to open the way to Mictlantecuhtli''s deepest lair.' FROM games WHERE igdb_id = 140910 ON CONFLICT (game_id, language_code) DO NOTHING;
