INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asteroids: Recharged', 'The original space shooter warps to the modern era! Asteroids: Recharged has been reimagined for modern gameplay, with vibrant visuals, powerful new abilities, and another original soundtrack from award-winning video game composer Megan McDuffee. Asteroids: Recharged creates a familiar, but revitalized and modern challenge to both old school and new high score chasers. And 30 unique and creative challenge levels take the space shooting game play into new territory, complete with local and global leaderboards.' FROM games WHERE igdb_id = 185729 ON CONFLICT (game_id, language_code) DO NOTHING;
