INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snoot Game', 'You play as Anon, a lonely, faceless, nobody, reject who finds himself in the dinosaur themed acid trip of a school named Volcano High. Here Anon meets the qt ptero known as Fang and their clown-vomit colored posse of reject friends and other associated thorns-in-the-side. All of whom, you can read about here. This game is a parody of Goodbye Volcano High.' FROM games WHERE igdb_id = 225989 ON CONFLICT (game_id, language_code) DO NOTHING;
