INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Make it Meme', 'Make it Meme is the free party game, about creating and rating memes: Each player gets a random meme and has to think of a text for the meme within a given time. After that, the players rate each other''s memes and award their Meme-Buddy. Whoever has collected the most points at the end wins!' FROM games WHERE igdb_id = 144934 ON CONFLICT (game_id, language_code) DO NOTHING;
