INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('space-jam-a-new-legacy-the-game', 154322, '2021-07-15', 34, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3cuo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar10c1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Jam: A New Legacy - The Game', 'As part of his scheme to become an all-powerful digital force, a rogue artificial intelligence named Al-G Rhythm has trapped basketball champion and global icon LeBron James inside the Warner Bros. server. While plotting to have his Goon Squad square off against LeBron and the Tune Squad in a high-stakes, high-tech basketball game, Al-G locks himself away in a hidden area of cyberspace. If LeBron, Bugs Bunny, and Lola Bunny can find all three pieces of the ""Legacy Code,"" they can use it to open up Al-G''s secret lair. But standing in their way is the rogue AI''s robot army... and members of the Goon Squad, The Brow and White Mamba. Put the hurt on Al-G''s army in this classic 2D brawler, using collectible cards to enlist help from other Tune Squad players. Will the Tune Squad''s teamwork be enough to stop Al-G Rhythm''s plans?' FROM games WHERE igdb_id = 154322 ON CONFLICT (game_id, language_code) DO NOTHING;
