INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Stop', 'Last Stop is a single-player third-person narrative adventure game set in present day London, where you play as three separate characters whose worlds collide in the midst of a supernatural crisis. An anthology drama, Last Stop is three stories in one. What connects these three strangers? Where will fate lead them? Developed in partnership with Annapurna Interactive and featuring an original soundtrack by BAFTA award winning composer Lyndon Holland, Last Stop is a game about secret lives, the ties that bind and how magic can be found in the mundane.' FROM games WHERE igdb_id = 125631 ON CONFLICT (game_id, language_code) DO NOTHING;
