INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summoner''s Mess', 'Enter a huge manor to fix the mess you''ve made summoning a beast from the depths. Look for the three sacred grimoires, hidden in a labyrinth made of rooms, closed doors and unsolved mysteries. Will you find it before it gets too dark and you''ll get consumed by the fears that we can''t see? Enjoy a short time trial experience, memorize the scenario and reach one of the three endings before your torch gets out completely!' FROM games WHERE igdb_id = 171815 ON CONFLICT (game_id, language_code) DO NOTHING;
