INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skul: The Hero Slayer', 'Skul: The Hero Slayer is an action-platformer that boasts rogue-like features such as everchanging and challenging maps. It will keep you on your toes, as you will never know what to expect. Guide ''Skul'' on his quest to single-handedly take on the Imperial Army and rescue his King from captivity, in an action-packed 2D game for the ages.' FROM games WHERE igdb_id = 127842 ON CONFLICT (game_id, language_code) DO NOTHING;
