INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alan-wake-remastered', 167611, '2021-10-05', 82, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co65aa.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5gdi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alan Wake Remastered', 'Alan Wake Remastered is an updated version of the original psychological horror action-adventure game developed by Remedy Entertainment. The game retains the core narrative, which follows bestselling thriller novelist Alan Wake as he struggles with writer''s block. He visits the small town of Bright Falls with his wife, Alice, in search of inspiration. Shortly after their arrival, Alice mysteriously disappears. Alan finds pages of a thriller novel he does not remember writing, with events from the manuscript coming to life. He faces supernatural entities called the "Taken," who are controlled by darkness. The remastered version features enhanced graphics and improved performance, but the gameplay and storyline remain consistent with the original, focusing on themes of reality, fiction, and the power of the written word. It also includes the two story DLCs "The Signal" and "The Writer".' FROM games WHERE igdb_id = 167611 ON CONFLICT (game_id, language_code) DO NOTHING;
