INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rune Infinite', 'Crush opponents while earning unique prizes in this fast-paced fantasy PvP brawler from Rune: a crypto gaming company pushing NFT games to new horizons. Choose your class, customize your avatar, and collect unique NFTs playing the third game in Rune’s ever-expanding Metaverse. Test your skills against players across the globe and rise above the rest as Champion of the Infinite Arena.' FROM games WHERE igdb_id = 195025 ON CONFLICT (game_id, language_code) DO NOTHING;
