INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cyber-shadow', 116650, '2021-01-26', 77, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob1s4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7ww.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyber Shadow', 'Dash, slice, and leap through masterfully designed levels filled with sharply honed ninja platforming action. Authentic 8-bit presentation with hand-crafted sprites, a detailed pixel aesthetic, and perfect controls. Modern touches like fluid animation, multi-layered parallax backgrounds, and evolved game design. Take down more than a dozen apocalyptic bosses, from enormous war machines to your synthetic clan rivals. Relive the authenticity of classic 8-bit challenge or experience it for the first time. with an added convenience or two.' FROM games WHERE igdb_id = 116650 ON CONFLICT (game_id, language_code) DO NOTHING;
