INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cozy Grove', 'Welcome to Cozy Grove, a life-sim game camping on a haunted, ever-changing island. As a Spirit Scout, you’ll wander the island’s forest each day, finding new hidden secrets and help soothe the local ghosts. With a little time and a lot of crafting, you’ll bring colour and joy back to Cozy Grove!' FROM games WHERE igdb_id = 144800 ON CONFLICT (game_id, language_code) DO NOTHING;
