INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Monster Party', 'Mega Monster Party is a classic multiplayer board game and minigame collection by AirConsole, perfect for passing time and ending friendships! Players use their smartphones as gamepads to control one of eight monstrous characters and conquer the board. Choose paths wisely, use secret items to gain advantage and stock up on coins by winning PvP minigames. Once you have the funds, find the Board Master and trade coins for monster minions to get ready for the multiplayer final battle.' FROM games WHERE igdb_id = 165840 ON CONFLICT (game_id, language_code) DO NOTHING;
