INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psychonauts 2', 'Psychonauts 2 is a platform-adventure game developed by Double Fine Productions and released in 2021. It continues the story of Razputin “Raz” Aquato, a young psychic who joins the international psychic espionage agency known as the Psychonauts. Gameplay combines platforming, exploration, and combat with psychic abilities such as telekinesis, pyrokinesis, and mental connection. Players journey through imaginative levels set inside characters’ minds, each reflecting their personalities and struggles.' FROM games WHERE igdb_id = 14741 ON CONFLICT (game_id, language_code) DO NOTHING;
