INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yolked', 'The Great Egg-Scape! Yolked is a kinetic, physics-based platforming romp where you take control of an anthropomorphic egg as it emancipates itself from one perilous predicament to the next! Climb, mantle, & swing past all sorts of environmental hazards & dastardly dangers as your fellow eggs cheer you on!' FROM games WHERE igdb_id = 178292 ON CONFLICT (game_id, language_code) DO NOTHING;
