INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lightblue', 'An ancient legend, a shattered family, an exorcist priest. lightblue is a first person survival horror game. You are Father Gabriel, an exorcist priest with the task of putting an end to the weird paranormal events that take place in Prettymountain Lake, the small village home of the famous legend about a strange albino girl with light blue hair mysteriously disappeared.' FROM games WHERE igdb_id = 144505 ON CONFLICT (game_id, language_code) DO NOTHING;
