INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Night Book', 'Night Book is an interactive occult thriller about an online interpreter who is tricked into reading an ancient book that summons a demon into her home. Loralyn works the night shift remotely from her home, live interpreting video calls from English to French and back again. Currently pregnant, with a husband working far away and caring for her mentally ill father, she is desperately trying to keep her family together and safe – but who is she prepared to sacrifice to survive? The fiancé, the baby, her father or herself?' FROM games WHERE igdb_id = 154902 ON CONFLICT (game_id, language_code) DO NOTHING;
