INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost of Tsushima: Director''s Cut', 'Ghost of Tsushima: Director''s Cut Includes: - Full game. - Iki Island expansion: New story, mini-games, enemy types and more. - Legends online co-op mode. - Digital mini art book by Dark Horse. - Director’s commentary: The creative team sits down with a renowned Japanese historian to look at the world of Ghost of Tsushima and how it compares to the real-life events that inspired it. - One Technique Point. - Charm of Hachiman’s Favour. - Hero of Tsushima Skin Set: Golden Mask, Sword Kit, Horse, Saddle.' FROM games WHERE igdb_id = 153700 ON CONFLICT (game_id, language_code) DO NOTHING;
