INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Nayuta: Boundless Trails', 'Nayuta no Kiseki (Trails of Nayuta) is an action-RPG developed by Nihon Falcom for PlayStation Portable. The game belongs to The Legend of Heroes series of role-playing video games, but is more action-oriented, and is not a mainline entry in the series. The Legend of Nayuta: Boundless Trails is an English version of the PSP classic "Nayuta no Kiseki (Trails of Nayuta)" and published by NIS America was released for Nintendo Switch, PlayStation 4, and Windows in North America on September 19, 2023, and in Europe and Oceania on September 22.' FROM games WHERE igdb_id = 42722 ON CONFLICT (game_id, language_code) DO NOTHING;
