INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ar Nosurge: Ode to an Unborn Star DX', 'On the planet Ra Ciela, humans and spiritual lifeforms known as Genoms once co-existed.That was a long time ago, and the world has since lost its former beauty.People have adapted to this poorer new environment and manage to eke out a living.One day, a race is known a the Sharl invaded and began kidnapping humans, who found themselves helpless against their mysterious Song Magic.All seemed lost until, unexpectedly, the Ancient Genoms returned to give people hope that one day there will be peace.' FROM games WHERE igdb_id = 139979 ON CONFLICT (game_id, language_code) DO NOTHING;
