INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('destruction-allstars', 134587, '2021-02-02', 67, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2gw6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1cgh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destruction AllStars', 'Stars and cars collide. Dominate the glittering global phenomenon of Destruction AllStars – the spectacular prime-time sport for dangerous drivers! Master the art of intense vehicle-based combat through timing, tactics and skills to cause colossal amounts of damage, destruction and devastation in vibrant arenas across the globe. Pile-on the destruction from behind the wheel or leap into the arena with a breathtaking reel of parkour action by dodging attacks, taking over vehicles or using abilities to disrupt the onslaught of incoming vehicles. Cause enough mayhem to power up your AllStars game-changing hero vehicle fueled with special abilities. A roster of 16 blockbuster Destruction AllStars are revved up and ready to compete in the name of entertainment and demolition. So, strap in for intense, explosive and unpredictable levels of free-flowing action and fight to be crowned the Global Destruction Federation Champion. It’s time to run, ram and slam. See you in the arena.' FROM games WHERE igdb_id = 134587 ON CONFLICT (game_id, language_code) DO NOTHING;
