INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hair of the Dog', 'After a mysterious explosion over Victorian London, Cummerbund Bandersnatch visits his uncle to find he''s been experimenting with a new formula he''s created in an attempt to give himself a "good time". Seduced by the promises in his uncle''s journal, Cummerbund decides to drink the same formula and discovers that his life will no longer be the same again (at least between the hours of 8pm - 8am daily). Can he reverse the effects of the formula before it''s too late?' FROM games WHERE igdb_id = 144638 ON CONFLICT (game_id, language_code) DO NOTHING;
