INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jurassic World Aftermath Collection', 'Jurassic World: Aftermath Collection is a suspenseful survival adventure. Crash-landing on Isla Nublar after the fall of the Jurassic World theme park, players find themselves trapped in an abandoned research facility when their mission to recover valuable information goes disastrously wrong. To survive, they’ll need to explore and solve puzzles while evading a menagerie of ferocious dinosaurs, including ravenous Pteranodons, cunning Velociraptors and the terrifying T. rex.' FROM games WHERE igdb_id = 223741 ON CONFLICT (game_id, language_code) DO NOTHING;
