INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Huntfeast', 'Prepare for the Werewolf Hunt! Misanthrope’s curse echoes through the woods of Lovengrad. Terrible monsters, led by the werewolf, hunt for their prey. An oppressive atmosphere paired with the thrill of hunting makes this game unlike any other. Begin the Huntfeast, where you are a hunter who hunts alone or with a friend.' FROM games WHERE igdb_id = 147431 ON CONFLICT (game_id, language_code) DO NOTHING;
