INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('insomnious', 176144, '2021-10-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co406c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1es7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Insomnious', 'Insomnious is a survival horror game inspired by Five Nights at Freddy''s, however with the added feature of being able to move around the room and get close and personal with the monsters to push them away. You are trapped in your room for the night, run around the room and hold back the night terrors while trying to get enough rest to fall asleep. These night terrors could come from everywhere, the window, the closest, the painting and even your bedroom door. But just confronting your fears by getting close enough to push them back will keep you safe for the night. Each night the monsters get more and more aggressive, on top of this the amount of time you have to sleep for increases each night. You have to manage defending yourself against the monsters of the night and getting sleep by making yourself vulnerable and resting in your bed. The main story mode will take you through 3 nights of progressively more and more difficult scenarios as you listen to your SAM try to get you to sleep. The challenge mode introduces a collection of 3 unique challenges to try to beat, it''s similar to story mode just without any additional lore. Finally the custom mode allows you to set your own challenges to try to survive. In custom mode you have the ability to change each monster''s difficulty (or even disable each monster), change the amount of time you need to sleep before surviving the night and even change the amount time it takes for the nightmare to kill you.' FROM games WHERE igdb_id = 176144 ON CONFLICT (game_id, language_code) DO NOTHING;
