INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Overrogue', 'Proceed through dungeon-like labyrinths building up your card deck in a roguelite style! There are up to 5 different labyrinth themes based on card genres like poison or graveyards. Enjoy a different deck experience each time you visit the labyrinth as the number of cards increase. Over 300 types of cards and 150 types of treasure await you, so combos and combinations are up to you. Let''s conquer the labyrinths and become the next Overlord!' FROM games WHERE igdb_id = 187834 ON CONFLICT (game_id, language_code) DO NOTHING;
