INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Capcom Arcade Stadium', 'Rediscover the era of 1up''s and quarter eaters with Capcom Arcade Stadium, a collection of Capcom''s most beloved arcade games spanning three decades! With 32 action-packed classics featuring some of the best games in Capcom history, such as Street Fighter II: The World Warrior and Strider, this compilation of retro games allows you to travel back in time to scratch that nostalgic itch or share your fond childhood memories with friends or family members!' FROM games WHERE igdb_id = 141546 ON CONFLICT (game_id, language_code) DO NOTHING;
