INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tormented Souls', 'Classic survival horror is back! Inspired by the original Resident Evil and Alone in the Dark series, Tormented Souls modernizes with a fresh twist on the fixed perspective adventure. While investigating the disappearance of twin girls at Winterlake, something terrible happens to Caroline Walker. Waking in the dead of night, naked and hooked up to some kind of outdated medical equipment in a bathtub, Caroline must fight for her life as she explores the halls of the abandoned mansion.' FROM games WHERE igdb_id = 138569 ON CONFLICT (game_id, language_code) DO NOTHING;
