INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twelve Minutes', 'Twelve Minutes is a real-time top-down interactive thriller with an accessible click and drag interface. Featuring James McAvoy, Daisy Ridley, and Willem Dafoe. The game blends the dream-like tension of The Shining with the claustrophobia of Rear Window and the fragmented structure of Memento.' FROM games WHERE igdb_id = 16612 ON CONFLICT (game_id, language_code) DO NOTHING;
