INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PixelJunk Raiders', 'SOS! Tantal is under attack by fiendish aliens bent on harvesting the population''s life force! Shake off that hypersleep and slash, smash, raid and rescue your way through hundreds of unique missions, all while unraveling the mystery of the enigmatic Keepers. Use State Share to share stages with the turrets, mines and other imprints you''ve left behind, or jump into another mercenary''s stage and use their imprints to your strategic advantage.' FROM games WHERE igdb_id = 144140 ON CONFLICT (game_id, language_code) DO NOTHING;
