INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Impossible Pixels', 'Impossible Pixels is a visually appealing bullet-hell pixel game with tons of action and an entertaining but not obligatory story. Use your mouse, patience and quick reflexes to evade a barrage of oncoming foes and make your way through 14+ unique, hand-crafted levels.' FROM games WHERE igdb_id = 140867 ON CONFLICT (game_id, language_code) DO NOTHING;
