INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Behind the Frame: The Finest Scenery', 'A narrative-driven puzzle game about collecting, fixing and painting. Enjoy the scenery en route in the world of Behind the Frame, and search for the secrets within. Recollect memories in the time corridor, and savor some beautiful little moments. Combining escape rooms and narrative games, Behind the Frame: The Finest Scenery presents a profoundly interactive storytelling of characters'' emotions and plot development. With 360° panorama techniques and an exquisite hand-painted art style, the game takes you into the world of Behind the Frame.' FROM games WHERE igdb_id = 148499 ON CONFLICT (game_id, language_code) DO NOTHING;
