INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Fire', 'Embark on an extraordinary journey through the desolated kingdom of Penumbra and discover the hidden secrets of this long-forgotten land. Explore mystical temples, encounter survivors and take on strange quests to collect valuable items. Along your adventure, slash your way through daunting adversaries, roam across mysterious and abandoned regions, leap through deadly traps and ultimately master the art of movement.' FROM games WHERE igdb_id = 131868 ON CONFLICT (game_id, language_code) DO NOTHING;
