INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('unholy-alliance-tower-defense', 163223, '2021-08-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3jei.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar11dk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unholy Alliance: Tower Defense', 'Enemies from this world and the dark world fight together in an “Unholy Alliance” to destroy your Extractors. Get ready to stand your ground and defeat enemy hordes using a vast arsenal of towers and special powers at your command. Fight on forests and wastelands, customizing your defensive strategy with different tower, special power, and Extractor upgrades and specializations! Bring your enemies death from above, send them moving backwards using Wind, place Mines in their way, block their way with a Decoy, or even Freeze them.' FROM games WHERE igdb_id = 163223 ON CONFLICT (game_id, language_code) DO NOTHING;
