INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toy Soldiers HD', 'Toy Soldiers HD is an action-packed strategy-based game in which you command antique WWI toy soldiers vying for control of the trench-filled battlefields of Europe. The remaster includes improved single and multiplayer gameplay, never-before played content, enhanced high-definition graphics and camera and sound. All previously released downloadable content will be included in the campaign flow. The original classic has been overhauled and upgraded with new content, skins, gameplay, expanded game modes, improved controls and graphical upgrades, as well as all the original DLC and a few new levels as well!' FROM games WHERE igdb_id = 147308 ON CONFLICT (game_id, language_code) DO NOTHING;
