INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('famicom-detective-club-the-missing-heir', 122244, '2021-05-14', 72, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30df.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ara1n.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Famicom Detective Club: The Missing Heir', 'A combined remake of the first game in the Famicom Tantei Club, Famicom Detective Club, series originally released in 1988 on the Family Computer Disk System in 2 parts. Solve a murder mystery surrounding a wealthy Japanese family Hunt for clues, talk to suspects, and explore the Japanese countryside after tragedy strikes the wealthy Ayashiro family. Filled with suspense, this tale follows an amnesia-stricken detective trying to unravel his own past amidst the horrors of a harrowing murder investigation. Play at home, on the go, or in your favorite reading nook—only on the Nintendo Switch system. Play Famicom Detective Club in English for the first time Originally released in Japan only, the Famicom Detective Club: The Missing Heir game has been localized with English text and modernized for Nintendo Switch. While the graphics, music, and sound effects have been recreated, players can choose the original 8-bit soundtrack. Discover a piece of Nintendo history with the Famicom Detective Club series of games.' FROM games WHERE igdb_id = 122244 ON CONFLICT (game_id, language_code) DO NOTHING;
