INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Genesis Noir', 'A noir adventure spanning time and space. You play as No Man, a watch peddler caught in a love triangle with other cosmic beings, Miss Mass and Golden Boy. When your affair turns into a bitter confrontation, you will witness a gunshot fired by a jealous god—otherwise known as The Big Bang. Jump into the expanding universe and search for a way to prevent or destroy creation and save your love.' FROM games WHERE igdb_id = 27413 ON CONFLICT (game_id, language_code) DO NOTHING;
