INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deluge', 'DELUGE (by riggy2k3) is the story of a village under siege. As the village of Figaro begins a dangerous tradition, an evil entity arrives to mark their own momentous occasion. When one of their minions goes rogue, he finds himself the key to Figaro''s survival. Will you protect the people of Figaro, or join in on the chaos?' FROM games WHERE igdb_id = 178161 ON CONFLICT (game_id, language_code) DO NOTHING;
