INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('vomitoreum', 142271, '2021-07-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2tm8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arwnw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vomitoreum', 'A dark and arid hellscape inspired by the likes of Metroid Prime and Dark Souls, Vomitoreum is an FPS Metroidvania set in an interconnected and nightmarish world. Explore a land that has been plagued with an eldritch infection, a horrible fog that blankets the world and turns it’s denizens into wretched mutants. Delve deep into the ruins of this plagued world and find a cure for this horrid blight. You are the Nephilem, a vessel born of cosmic ash and the churning souls trapped within graves. Created as a being able to survive the hellish environment and search for a way to make the fog recede, you will scour the lands in search of tools and weaponry that will be useful on your journey. The Nephilem’s end goal is to make the infection and the fog recede, destroy the horrible demons plaguing the land, and let life flourish once again.' FROM games WHERE igdb_id = 142271 ON CONFLICT (game_id, language_code) DO NOTHING;
