INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aliens: Fireteam Elite', 'Set in the iconic Alien universe, Aliens: Fireteam Elite is a cooperative 3rd-person survival shooter that drops your fireteam of hardened marines into a desparate fight to contain the evolving Xenomorph threat. Create and customize your own Colonial Marine, choosing from an extensive variety of classes, weapons, gear and perks, battling overwhelming odds in this heart-pounding survival shooting experience.' FROM games WHERE igdb_id = 144153 ON CONFLICT (game_id, language_code) DO NOTHING;
