INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'New World: Aeternum', 'Explore a thrilling, open-world MMO filled with danger and opportunity where you''ll forge a new destiny for yourself as an adventurer shipwrecked on the supernatural island of Aeternum. Endless opportunities to fight, forage, and forge await you among the island''s wilderness and ruins. Channel supernatural forces or wield deadly weapons in a classless, real-time combat system, and fight alone, with a small team, or in massed armies for PvE and PvP battles—the choices are all yours.' FROM games WHERE igdb_id = 24654 ON CONFLICT (game_id, language_code) DO NOTHING;
