INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gutsy the Guinea Pig', 'In a desperate attempt to regain their former glory, the cats of the Internet have hatched a devious plot to reinvigorate their icons of old. How will they do this? By stealing the life force of defenseless guinea pigs! Help Gutsy the Guinea Pig navigate a series of magnetic obstacles to retrieve the keys to his friends’ freedom.' FROM games WHERE igdb_id = 185736 ON CONFLICT (game_id, language_code) DO NOTHING;
