INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boom Karts: Multiplayer Kart Racing', 'Boom Karts is a free-to-play online kart racing game where speed is the goal! Beat your opponents to the podium or tackle the challenges to earn your bragging rights. Challenge your friends in online multiplayer games with custom lobbies. Upgrade and customize your karts and avatar with items earned through game play. If you have any issues or need any assistance then please email our support team at: boomkarts-support@zaibatsu.fi' FROM games WHERE igdb_id = 144982 ON CONFLICT (game_id, language_code) DO NOTHING;
