INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'As Fast As Possible', 'AFAP includes single player levels, in which the goal is to master the levels as fast as possible. During the level a timer runs in which you must have passed the level. For each level there is a leaderboard with the fastest times. Difficult jumps, ice slides and wallrunns awaid you.' FROM games WHERE igdb_id = 145819 ON CONFLICT (game_id, language_code) DO NOTHING;
