INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blazing Rangers', 'Blazing Rangers is an original one-screen action game for NES-compatible hardware, realized in the style of ''80s arcade games. The setting and goal is easily explained: You are a firefighter with the task to rescue all kids from a dangerous fire site. Equipped with a water hose, you can choose between two characters and will fight an ever-growing wall of fire and a plethora of dangerous enemies to open up the way and save the children. It''s also important not to dawdle around - they might get burned if you don''t take some risks and hurry to their rescue!' FROM games WHERE igdb_id = 143052 ON CONFLICT (game_id, language_code) DO NOTHING;
