INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('necromunda-hired-gun', 144725, '2021-06-01', 62, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co31dd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7i4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Necromunda: Hired Gun', 'Pick your contracts. Hunt your targets. Collect the bounty. Navigate an ocean of crime and corruption to balance the bloody ecosystem of Necromunda as a merciless hired gun. The money’s good, the dog’s loyal, and the gun’s reliable – but can you survive the hunt? Necromunda: Hired Gun is an indie fast-paced, violent, and thrilling FPS set in the darkest reaches of Warhammer 40,000’s most infamous hive city. For the right price, eliminate the most notorious gangers and mutants. Your armory is a sprawling arsenal. Your body is enhanced with a dozen customizable augments to run on walls and leap over chasms. Your cyber-mastiff will sniff out and kill enemies for you, while your grappling hook allows quick, agile traversal of the massive environments. - An indie fast-paced FPS in the Warhammer 40,000 universe - Upgrade and fight alongside your loyal cyber-mastiff - Endless weapon and augment customization - Upgrade, advance, and level up as you collect bounties' FROM games WHERE igdb_id = 144725 ON CONFLICT (game_id, language_code) DO NOTHING;
