INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ender Lilies: Quietus of the Knights', 'Ender Lilies is a dark fantasy 2D Action RPG about unraveling the mysteries of a nation destroyed by a cataclysmic event. The fallen Kingdom of End is a tragic and beautiful world featuring a majestic castle, submerged forests and forbidden underground areas. On this sorrowful journey, encounter horrific enemies against whom a moment of inattention could be fatal. By releasing foes from their undying curse, you may gain their strength. Overcome the hardships of your journey and uncover the truth with the aid of the fallen knights.' FROM games WHERE igdb_id = 138858 ON CONFLICT (game_id, language_code) DO NOTHING;
