INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Town of Passion', 'Town of Passion is an adventure styled RPG, where you play as a common villager living in the small town of Valencia; a town full of many secrets and populated only by beautiful women. After stumbling into an unknown realm, the villager learns that there''s an important role for him to fulfill: utilize Pleasure to save those that watch over Valencia! Solve tricky puzzles! Help out around Valencia and build relationships with the Villagers! And go out and explore the exciting world filled with lustful Monster Girls!' FROM games WHERE igdb_id = 127633 ON CONFLICT (game_id, language_code) DO NOTHING;
