INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unpacking', 'Unpacking is a zen puzzle game about the familiar experience of pulling possessions out of boxes and fitting them into a new home. Part block-fitting puzzle, part home decoration, you are invited to create a satisfying living space while learning clues about the life you’re unpacking. Over the course of eight house moves, you are given a chance to experience a sense of intimacy with a character you never see and a story you’re never told.' FROM games WHERE igdb_id = 115843 ON CONFLICT (game_id, language_code) DO NOTHING;
