INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Wide Hack', 'World Wide Hack is an MMO simulation game about realistic hacking and cybersecurity. Collect the most effective sets of hacking and security tools, gather assets, and improve your computer to hack others, control parts of the network, or create the best websites and tools which will help other hackers and make you rich! Work with others to make your experimental activities useful for your faction and lead with them the world in the right direction.' FROM games WHERE igdb_id = 138931 ON CONFLICT (game_id, language_code) DO NOTHING;
