INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Golf: Super Rush', 'Tee off with family and friends in the biggest Mario Golf game yet! Hit the green with up to four players locally or online and golf with familiar Mushroom Kingdom characters. Modes range from Standard Golf to the energetic Speed Golf and an RPG-like golf adventure in story mode. Intuitive motion or button controls, a shot gauge that adapts to the curve of the course, and other new features make it easy for both new players and seasoned pros to drive and putt with power.' FROM games WHERE igdb_id = 143609 ON CONFLICT (game_id, language_code) DO NOTHING;
