INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aviano', 'Aviano is an exploration game from other worlds, where the player plays an archaeologist who wants to solve a mystery! And it will take him to fly with his hang glider in other ways, challenging your pilot skills until the end of each level. The controls are easy to understand but skill based, the physics-based flight model. It offers a realistic flight experience, similar to a real flying wing, am with higher speeds to entertain and give speed sensations to the player…' FROM games WHERE igdb_id = 151626 ON CONFLICT (game_id, language_code) DO NOTHING;
