INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac-Man Live Studio', 'PAC-MAN LIVE STUDIO is a game published by Amazon playable on the Twitch website. It lets you play co-op multiplayer PAC-MAN with friends online and publish mazes to the community. It was created in celebration of PAC-MAN’s 40th Anniversary.' FROM games WHERE igdb_id = 134152 ON CONFLICT (game_id, language_code) DO NOTHING;
