INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Geyser: Couriers of Darkness', 'Black Geyser: Couriers of Darkness is an isometric, party and XP based, real-time RPG (with pause option) set in the world of Yerengal. A game that combines immersive graphics and brand-new features with virtues of the classic RPGs we all loved! Solve mysteries, fight epic battles, help beggars and kings alike, outwit swindlers and gods, and never forget: greed has many forms and many names!' FROM games WHERE igdb_id = 57853 ON CONFLICT (game_id, language_code) DO NOTHING;
