INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil 4 VR', 'Explore the iconic world of Resident Evil 4 in this all-new version, entirely made for VR. Step into the shoes of special agent Leon S. Kennedy on his mission to rescue the U.S. President''s daughter who has been kidnapped by a mysterious cult. Find your way through a rural village in Europe, come face to face with challenging enemies, and uncover secrets and gameplay that have revolutionized the entire survival horror genre. Battle horrific creatures infected by the Las Plagas parasite and face off against aggressive enemies including mind-controlled villagers and discover their connection to Los Illuminados, the cult behind the abduction.' FROM games WHERE igdb_id = 172560 ON CONFLICT (game_id, language_code) DO NOTHING;
