INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F1 2021', 'Every story has a beginning in F1 2021! Enjoy the stunning new features, including the thrilling story experience ''Braking Point'', two-player career, and get even closer to the grid with ''Real-Season Start''. Take your team to the top in the acclaimed ten-year ''My Team'' career mode, or race head-to-head in split-screen and multiplayer. Immerse yourself in the greatest racing spectacle on the planet and race with the authentic lineup of twenty heroic drivers and ten iconic teams from the 2021 season.' FROM games WHERE igdb_id = 145838 ON CONFLICT (game_id, language_code) DO NOTHING;
