INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('revenants', 186223, '2021-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4bej.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scf3y0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Revenants', 'Become a professional occult investigator, relying on your cutting edge technology from 2030 to locate, trap and battle demonic forces, all whilst solving the mystery of the occult crimes. You''ll need a sharp eye to locate evidence throughout each case, documenting all you can find with your camera whilst you explore the abandoned crime scenes. As a professional investigator, you''ll also need to put the case together, connecting the dots and discovering who the culprits were. Choose which technology you want to take on each case. Do you want to hunt down the revenant and trap it? Or set up surveillance and sensors so you can stay away from it. Either way, you''ll always have your trusty tablet at your side, allowing you to picture any evidence you find and keep demonic forces at bay. This is no regular camera, the Pentacam was built using ancient ritual magics. The demons should be afraid of you as you charge up the Pentacam and manifest them further with each shot. Until they are eventually captured within the device. Revenants will be released in an episodic / case structure. With the base game containing the first case, and the next cases being released as they are developed as DLC.' FROM games WHERE igdb_id = 186223 ON CONFLICT (game_id, language_code) DO NOTHING;
