INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kathy-rain-directors-cut', 142770, '2021-10-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ova.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru2d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kathy Rain: Director''s Cut', 'Award-winning adventure Kathy Rain returns in the Director’s Cut, featuring an extended story with more puzzles to solve and new areas to explore. Witness the emergence of an iconic detective as you uncover a dark and sinister truth hiding behind the calm exterior of a small rural town. Director''s Cut Features: - Extended storyline with a prolonged ending, hundreds of lines of additional dialogue, and multiple new areas to explore. - Several new major puzzle chains and many small additions and tweaks of existing puzzles. - Enlarged game environments to fill up the entire screen without any black bars on the sides. - Made countless visual improvements, such as more character animations, better lighting/shadows and extra weather effects. - Streamlined mouse controls with an intuitive single click interface. - Controller support done right. Lean back in your chair and take smooth direct control of Kathy, with no messy cursor getting in the way. - Expanded and remixed soundtrack by the original composer, Daniel Kobylarz. - Five brand new motorcycle designs to unlock and customize the Katmobile with.' FROM games WHERE igdb_id = 142770 ON CONFLICT (game_id, language_code) DO NOTHING;
