INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'What the Dub?!', 'What The Dub?! is a multiplayer party game where each player overdubs missing dialogue from hilariously awful B-movies, outdated PSAs, and bizarre industrial films, with their own witty (or just plain stupid) dubs! Players watch the dubs and vote on the best one. The player with the highest score at the end of the game wins! What The Dub takes "bad movie night" and expands it into an interactive, fast-paced, multiplayer game that friends and family, both local and afar, can enjoy!' FROM games WHERE igdb_id = 144808 ON CONFLICT (game_id, language_code) DO NOTHING;
