INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nickelodeon All-Star Brawl', 'The largest collection of Nickelodeon characters ever assembled in a fighting game! Nickelodeon All-Star Brawl brings together your favorite Nickelodeon characters for one bombastic battle. With a power-packed cast of heroes from the top shows within the Nickelodeon universe, face-off with all-stars from SpongeBob Squarepants, Teenage Mutant Ninja Turtles, The Loud House, Aaahh!!!, Real Monsters, Avatar, The Wild Thornberrys, Hey Arnold!, Rugrats, and many more to determine ultimate dominance. With unique move sets and attacks drawn directly from their identifiable personalities, each character has its own style of play enabling endless hours of enjoyable action for Nickelodeon''s legion of fans.' FROM games WHERE igdb_id = 156151 ON CONFLICT (game_id, language_code) DO NOTHING;
