INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('moonglow-bay', 145073, '2021-10-26', 68, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2wa8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arwtk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moonglow Bay', 'Moonglow Bay is set along the Eastern Canadian coastline during the 1980s and offers players a diverse and emotionally charged story, complemented by a relaxing, slice-of-life fishing RPG. You play as a rookie angler, struggling to fulfil your partner’s final wish by keeping a business afloat in the face of impending bankruptcy. Whether playing solo or with a friend in drop-in-drop-out local co-op, you’ll need to cook your catch of the day, then sell a variety of recipes to upgrade your shop, gear, and fishing boat. Combining a playful voxel art style with a sumptuous soundtrack, your journey is split into several distinct story arcs featuring a fully-inhabited town to traverse and the potential for epic encounters with the rumoured Mystical Monsters of Moonglow. With your journal and rod in hand, explore the furthest reaches of the ocean, from frigid glaciers to boiling geysers, and learn to cast nets, set traps and fish through ice, documenting over 100 varied aquatic species while uncovering the secrets of Moonglow Bay.' FROM games WHERE igdb_id = 145073 ON CONFLICT (game_id, language_code) DO NOTHING;
