INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('plants-vs-zombies-battle-for-neighborville-complete-edition', 142819, '2021-03-18', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2usr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arb3f.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Plants vs. Zombies: Battle for Neighborville - Complete Edition', 'Tackle hilarious missions and defeat epic bosses in the Weirding Woods, Mount Steep, and Neighborville Town Center to collect medals and unlock outrageous outfits. Party with up to three friends and goof around in Giddy Park or dive into some 8v8 multiplayer in Turf Takeover, vanquishing opponents, blasting gnome bombs, bouncing on pink ooze – it’s the most fun you’ll have since sliced bread. Take your system anywhere, and prepare to kick some grass offline and online in a plant-on-zombie conflict that will take you to the outer edges of Neighborville and back again! - Venture to the Outer Edges of Neighborville Offline - Discover Giddy Park, PvE free-roam regions and Private Play modes all without an internet connection. - Customize Every Character for Battle - Earn in-game coins only through play, and spend them at the Rux store to unlock cool customization items, characters and perks. - Play with Your Favorite People -Party with up to three friends and goof around in Giddy Park or dive online into some 8v8 multiplayer in Turf Takeover, vanquishing opponents across a gigantic suburban skirmish. - Motion Controls & Touch Menus - Use motion controls for aiming, with a full range of settings to customize to your preference. Interact with UI menus throughout the game using touch input including map zoom. - Prize Map Selector - Choose from and interact with all 12 prize maps at any time, and exchange prize bulbs for unbeleafable rewards!' FROM games WHERE igdb_id = 142819 ON CONFLICT (game_id, language_code) DO NOTHING;
