INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Drop', 'Dragon Drop is a frantic couch-multiplayer game where lovable dragons try to drop the blocks out from below their opponents. Drop the dragons! Don''t get dropped! In this groundbreaking game of timing, tactics and quick twists of luck, your fire breath temporarily wipes a line of cuboid platforms away. Try to stay on while dropping your rivals, but don''t delay your next step, it could be your last! Hatch into Dragon Drop, and may the last (and best) dragon win!' FROM games WHERE igdb_id = 159251 ON CONFLICT (game_id, language_code) DO NOTHING;
