INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Class of ''09', 'This is the anti-visual novel. Instead of playing as some guy magically able to score with beautiful anime girls, YOU play the anime girl and create mass chaos in the lives of your potential "suitors". Earnest comedy, social accuracy, and late 2000''s aesthetic await you in Class of ''09!' FROM games WHERE igdb_id = 152962 ON CONFLICT (game_id, language_code) DO NOTHING;
