INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('curse-of-the-dead-gods', 125373, '2021-02-23', 84, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1zv7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6nk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Curse of the Dead Gods', 'You seek untold riches, eternal life, divine powers - it leads to this accursed temple, a seemingly-infinite labyrinth of bottomless pits, deadly traps, and monsters. Your greed will lead you to death, but that is not an escape. Rise to fight again. Delve deeper again. Defy the malignant deities that linger in this place. Battle through hordes of enemies in dark, cavernous passages filled with traps and secrets of all sorts - fire-spewing statues, explosives, hidden spikes, and worse. Collect mystical Relics and an arsenal of weapons to make yourself unstoppable. Corruption builds in you with every step - encourage or ignore it, but each powerful curse can be a double-edged sword. - A skill-based roguelike exploring a cruel, dark temple made of endless rooms and corridors - Swords, spears, bows, guns - wield these and many more - Unique curses influence each attempt, putting a twist on every action - Dozens of enemies, with powerful champions and deadly bosses to face off against' FROM games WHERE igdb_id = 125373 ON CONFLICT (game_id, language_code) DO NOTHING;
