INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('my-friend-peppa-pig', 148289, '2021-10-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3irs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar148d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Friend Peppa Pig', 'Start a fun-filled adventure by becoming Peppa Pig’s new friend! Take your first steps into Peppa’s world by creating your character and choosing your clothes. If you want to be a fox in a pirate hat, you can. Or be a rabbit in a nice dress and sunglasses – it’s your choice. There are so many possibilities, even before you ring the doorbell at Peppa’s house. What happens in your story is all up to you. Everywhere you go, Peppa will suggest fun things to do – just like you’re in an episode of the TV show. Will you help Daddy Pig find his lost glasses in the house? Can you guess the animal from the tracks you follow in the Forest? When it rains, you’ll surely want to jump in muddy puddles – just don’t forget your boots! All your favorite characters are here, and they’re excited to meet you. Play with George and Mummy Pig at Peppa’s House. Sing with Madam Gazelle and the other children at Peppa’s School. Visit the Beach, Snowy Mountain, the Museum… even Potato City! Every play session is a new experience, as you choose new paths and try new things with your friend Peppa Pig.' FROM games WHERE igdb_id = 148289 ON CONFLICT (game_id, language_code) DO NOTHING;
