INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlefield 2042', 'Battlefield 2042 marks the return to the iconic all-out warfare of the franchise. Adapt and overcome dynamically-changing battlegrounds with the help of your squad and a cutting-edge arsenal. With support for 128 players, prepare for unprecedented scale on vast environments. Take on massive experiences, from updated multiplayer modes like Conquest and Breakthrough to the all-new Hazard Zone.' FROM games WHERE igdb_id = 125166 ON CONFLICT (game_id, language_code) DO NOTHING;
