INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Far Cry 6', 'Dive into the gritty world of a modern-day guerrilla revolution to liberate a nation from its oppressive dictators. Welcome to Yara, a tropical paradise frozen in time. Far Cry 6 thrusts players into a modern-day guerrilla revolution. As dictator of Yara, Anton Castillo is intent on restoring his nation back to its former glory by any means, with his son, Diego, following in his bloody footsteps. Become a guerrilla fighter and liberate Yara.' FROM games WHERE igdb_id = 126290 ON CONFLICT (game_id, language_code) DO NOTHING;
