INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road 96', 'Road 96 is a crazy, beautiful road-trip. The discovery of exciting places, and unusual people on your own personal journey to freedom. An ever-evolving story-driven adventure inspired by Tarantino, The Coen Brothers, and Bong Joon-ho. Moments of action, exploration, contemplative melancholy, human encounters and wacky situations. Set against a backdrop of authoritarian rule and oppression. A stunning visual style, a soundtrack filled with 90s hits, and a thousand routes through the game combine so each player can create their own unique stories on Road 96.' FROM games WHERE igdb_id = 141543 ON CONFLICT (game_id, language_code) DO NOTHING;
