INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('midnight-caravan', 104278, '2021-06-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3nvh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ardj3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Caravan', 'Midnight Caravan, a richly illustrated choose-your-own-adventure with an unique narrative arc set in an age renowned for its shadiness, where nothing is only what it appears to be. Midnight Caravan is an interactive story that puts the player in the shoes of a man, living a gripping story of vengeance, politic, intrigues, espionage and much more, through the entire Italian peninsula. The game tells the story of a caravan of outcasts led by the player, involved in a dangerous travel across the country: from Rome to Venice, passing through Florence. Gamblers, prostitutes, murderers, thieves: though moral choices and crimes set the tone for this story-driven gem. A creepy atmosphere envelops the journey: will you protect your people or will you pursue your own fortune? Experience the nomadic life of a caravan leader, rejected by everybody without a reason, chased by justice and hunted by unknown enemies!' FROM games WHERE igdb_id = 104278 ON CONFLICT (game_id, language_code) DO NOTHING;
