INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Can''t Drive This', 'Drive your car WHILE your friend builds the road in front of you! Oh, and don''t go below 20mph OR YOU''LL EXPLODE! Like in that Sandra Bullock movie, in which she kinda does the same thing, but on a bus. Also, she doesn''t explode (Spoiler alert). Also, Keanu Reeves was in the movie.' FROM games WHERE igdb_id = 27097 ON CONFLICT (game_id, language_code) DO NOTHING;
