INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Nightmares II', 'Little Nightmares II is a suspense-adventure game in which you play as Mono, a young boy trapped in a world that has been distorted by the humming transmission of a distant tower. With Six, the girl in a yellow raincoat, as his guide, Mono sets out to discover the dark secrets of The Signal Tower and save Six from her terrible fate; but their journey will not be straightforward as Mono and Six will face a gallery of new threats from the terrible residents of this world. Will you dare to face this collection of new, little nightmares?' FROM games WHERE igdb_id = 121760 ON CONFLICT (game_id, language_code) DO NOTHING;
