INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloody Raid', 'Bloody Raid is a tactical team-based PvPvE action shooter where the Hunters fight the Infected in mysterious Zones. Several competing teams enter a Zone with a goal to be the first to find and collect valuable biosamples and evacuate with the loot as fast as possible. Fallen players can rise again in the Zones, though not quite the same as before.' FROM games WHERE igdb_id = 148878 ON CONFLICT (game_id, language_code) DO NOTHING;
