INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farmageddon: A Cattle Royale', 'Farmageddon: A Cattle Royale is a series of cow puns masquerading as a new kind of roguelite. Try to claim the divine pasture while picking up items along the way to improve your build! But be careful: every player''s run is recorded, and you''ll be playing against the ghosts of every run attempted in the same day, including your own!' FROM games WHERE igdb_id = 142059 ON CONFLICT (game_id, language_code) DO NOTHING;
