INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oceanhorn: Chronos Dungeon', 'Chronos Dungeon is a dungeon crawler geared towards local multiplayer. Inspired by 16-bit classics, but enhanced with randomized modifiers making each level unique, Chronos Dungeon has players collecting loot and fighting side by side in an epic quest against the god that set the events of the main Oceanhorn saga in motion, Chronos himself.' FROM games WHERE igdb_id = 142346 ON CONFLICT (game_id, language_code) DO NOTHING;
