INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asterix & Obelix: Slap Them All!', 'Romans, pirates and boars beware! The famous Gauls Asterix and Obelix are coming back for a brand new adventure! Unlike the magic potion, the gameplay recipe is pretty straight forward and holds no secrets. Think about the core mechanics defining the beat’em up genre and sprinkle with some local co-op! By Jupiter, by Teutates.. These Gauls are crazy!' FROM games WHERE igdb_id = 145062 ON CONFLICT (game_id, language_code) DO NOTHING;
