INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Melvor Idle', 'Inspired by RuneScape, Melvor Idle takes the core of what makes an adventure game so addictive and strips it down to its purest form! Melvor Idle is a feature-rich, idle/incremental game combining a distinctly familiar feel with a fresh gameplay experience. Maxing 20+ skills has never been more zen. Whether you''re a newbie, a hardened veteran, or simply someone looking for a deep but accessible adventure that easily fits around a busy lifestyle, Melvor is an addictive idle experience unlike any other. Do you have what it takes to conquer Melvor?' FROM games WHERE igdb_id = 141130 ON CONFLICT (game_id, language_code) DO NOTHING;
