INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Smurfs: Mission Vileaf', 'Go on an adventure to save your forest! Gargamel, the evil sorcerer just created the vileaf, a plant that has the ability to attract and capture the Smurfs... but it''s also toxic! Embody 4 iconic Smurfs and heal the plants on your way to Gargamel''s hovel: the whole forest depends on you!' FROM games WHERE igdb_id = 149960 ON CONFLICT (game_id, language_code) DO NOTHING;
