INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('speed-limit', 117106, '2021-02-16', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2i09.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/araok.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speed Limit', 'Speed Limit is a non-stop genre-warping arcade experience that never slows down. No cuts, no lapses in the chaos, Speed Limit is an old-school action extravaganza boiled down to its core elements: Hard. Fast. Addictive. As soon as you think you''ve learned how the game works, it changes to a completely different genre, taking you through the history of the golden arcade era. Fight through a nail-biting side-scrolling shooter, race to the finish in an explosive top-down car chase, take flight in a thrilling fake-3D dogfight, and expect the unexpected. Speed Limit seamlessly changes styles, transforms the gameplay, and offers new challenges the moment you feel comfortable. Running. Driving. Flying. Dying (many, many times!) - From the moment you click play to the moment you die, you are in control. And you will die. A lot.' FROM games WHERE igdb_id = 117106 ON CONFLICT (game_id, language_code) DO NOTHING;
