INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spelunker-hd-deluxe', 145280, '2021-07-15', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3pmf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arytn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spelunker HD Deluxe', 'Spelunker HD returns! Spelunker HD, which was released for PlayStation 3 in 2009 and won the PlayStation Store Special Award at the PlayStation Awards that year, has been revived with a full remake on PlayStation 4 and Switch as Ganso Minna de Spelunker. Ganso Minna de Spelunker is an action game in which the cave explorer Spelunker, said to be “the weakest chracter in video game history,” explores caves full of mystery. With 100 stages consisting of abandoned mines, underground lakes, ancient ruins, glaciers, and more, Spelunker’s goal is to reach the depths of each cave. Caves are full of dangers including natural terrain, cave creatures, and malicious traps—and enemies and traps that appear to be traces of an unknown civilization will appear in the latter half of the cavern. Spelunker must overcome these obstacles by properly utilizing items such as bombs, flares, portable fans, and more, as well as his jump technique. But be cautious, as Spelunker is quite weak! If you fall from your own height, or get hit by bat poop, you will die. Spelunker’s weakness, or his “fragile constitution,” gives the game a moderate sense of tension and rhythm, making it more interesting as an action game.' FROM games WHERE igdb_id = 145280 ON CONFLICT (game_id, language_code) DO NOTHING;
