INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mr-prepper', 81680, '2021-03-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co69ay.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arjyw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Prepper', 'Mr. Prepper is about to be prepared. You know something is wrong, the risk of a nuclear war is in the air and you need to be prepared for what''s coming. They promised freedom but dealing with your paranoid government is just another day in this survival crafting game; - Build an underground shelter - Craft machines that can keep you alive; farms, greenhouses, tools, vehicles etc. - Trade with neighbors, give them what they need, get what is useful to you - Make a plan, you need to get out of this country - Beaware of the secret police, they don''t want you to be prepared, they want you to stay in their control Mr. Prepper is the guy who live in a country which once was the land of freedom but step by step its government changed everything. If you don''t obbey - you dissapear. Be as they want you to be or be gone. Our hero decided to opose, to get out of this delusion of life. The only way for him to hide his plans and his doings is to build an underground shelter and construct a machine that helps him get out across the border. But he will need materials, materials so rare in this world - help him get them, help him escape without being discovered.' FROM games WHERE igdb_id = 81680 ON CONFLICT (game_id, language_code) DO NOTHING;
