INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Echo', 'When Chase decides to write a college report on a case of mass hysteria that occurred in his old home town of Echo, he uses the opportunity to get his group of childhood friends back together for the week. However, a tragedy from their past weighs heavily on their minds, and the desolate desert town finds itself on the brink of disaster once more in this atmospheric slow-burn visual novel.' FROM games WHERE igdb_id = 136715 ON CONFLICT (game_id, language_code) DO NOTHING;
