INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abdogtion', 'Some creepy presence lurks deep in the snowy mountains. Locals have been experiencing a series of strange abductions, but none of them were brave enough to do anything. Until the day our main protagonist lost his dog. Powered by little more than his fists, he''s determined to break through the frozen wastes into the heart of the forest just to get his best friend back.' FROM games WHERE igdb_id = 287439 ON CONFLICT (game_id, language_code) DO NOTHING;
