INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Danganronpa S: Ultimate Summer Camp', 'Your favorite Danganronpa characters return for a hope-filled Summer! With an all-star dream lineup of characters from each Danganronpa game, gather Hope Fragments at a tropical resort. Explore Jabberwock Island and develop your Dangan characters. Gather money through battle and upgrade your equipment, then defeat bosses and move on to the next island!' FROM games WHERE igdb_id = 152366 ON CONFLICT (game_id, language_code) DO NOTHING;
