INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'B.ARK', 'Team B.ARK is reporting for duty! Pugs, cats, bears, and bunnies are saving the solar system in a space-exploring adventure that you and your pals won’t forget! Pilot powerful yet adorable ships as you team up against waves of revenge-seeking underwater animal life. Navigate the galaxy, create unique attack strategies with your crew, upgrade your ships, and explore the solar system to find challenging intergalactic tales!' FROM games WHERE igdb_id = 131870 ON CONFLICT (game_id, language_code) DO NOTHING;
