INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('virtualsociety', 142328, '2021-01-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2o80.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1qzn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VirtualSociety', 'Explore the virtual world and customize every detail, from your character to your home, and much more.  Choose how you look and dress, then decide how you want to live. Design and build incredible homes for each family, then decorate them with your favorite furniture and design.  Have a walk in town and talk to the other players to learn more about their lives. Challenge them on multiplayer games or spend your life with them!  Tell your own stories in your own way as you develop relationships, pursue your career and life dreams, and immerse yourself in this amazing game where the possibilities are endless.  Play with your friends, play with life!' FROM games WHERE igdb_id = 142328 ON CONFLICT (game_id, language_code) DO NOTHING;
