INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('where-the-heart-leads', 135615, '2021-07-13', 79, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4cb5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1bui.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where the Heart Leads', 'On the kind of stormy night that can change a person''s destiny, an enormous sinkhole opens in the middle of Whit Anderson''s farm. Braving the rumbling thunder and the driving rain, Casey - their curious Golden Retriever - ventures too close to the gaping maw and tumbles in. Desperate to save her, Whit descends into the darkness, and emerges in a realm beyond his imagining. In this strange world, constantly shifting like the stops and starts of a dream, Whit bears witness to the story of his life and gains the power to change it.' FROM games WHERE igdb_id = 135615 ON CONFLICT (game_id, language_code) DO NOTHING;
