INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Unite', 'Team up and take down the opposition in Pokémon’s first 5-on-5 strategic team battle game! Join Trainers from around the world as they head for Aeos Island to compete in Unite Battles! In Unite Battles, Trainers face off in 5-on-5 team battles to see who can score the most points within the allotted time. Teamwork is key as you and your teammates defeat wild Pokémon, level up, evolve your own Pokémon, and work to prevent the opposing team from scoring points. Put your teamwork to the test, and take home the win!' FROM games WHERE igdb_id = 135381 ON CONFLICT (game_id, language_code) DO NOTHING;
