INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disgaea 6: Defiance of Destiny', 'The first new Disgaea game in six years is here! Meet Zed, a zombie that has risen above them all except one - a God of Destruction! Can a mere Netherworld zombie rise up and destroy a god? Find out in the newest installment of the Disgaea series! Features such as Super Reincarnation, 3D visuals (a first for this series), and adjustable gameplay settings make this the perfect game for both new and old Disgaea fans!' FROM games WHERE igdb_id = 138953 ON CONFLICT (game_id, language_code) DO NOTHING;
