INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Eternal Cylinder', 'In The Eternal Cylinder, players control a herd of adorable creatures called Trebhums and must explore a strange alien world filled with exotic lifeforms, surreal environments, and the constant threat of the Cylinder, a gargantuan rolling structure of ancient origin which crushes everything in its path. This unique ecosystem is a massive, procedurally generated land with unique animal AI, real-time world destruction, and organic exploration and puzzle design to create emergent gameplay that ensures no two playthroughs are ever the same.' FROM games WHERE igdb_id = 121715 ON CONFLICT (game_id, language_code) DO NOTHING;
