INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City of Gangsters', 'Start a crime syndicate from nothing, and grow it into a well-oiled money machine in City of Gangsters, a mafia management simulation game. Build speakeasies and illegal distilleries. Manage production chains and resource distribution. Smuggle goods from out of town and bribe the police to look the other way. Grow a powerful crew and keep your rivals under your thumb. Eliminate competition and rule the city. But most importantly, keep the money flowing.' FROM games WHERE igdb_id = 144267 ON CONFLICT (game_id, language_code) DO NOTHING;
