INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pnevmo-capsula-domiki', 155872, '2021-10-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3vgk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvyv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pnevmo-Capsula: Domiki', 'The action of the steampunk game "Pnevmo-Capsula: Domiki" takes place in Russia of the 70s. The game opens the door to the history of parallel Russian reality, where society and technologies developed along the path of cultivating harsh mechanics. All houses are connected by a system of tiny rails along which you have to move in the form of a steampunk tiny capsule. Search and activation of the hidden mechanisms such as springs, telephones and various incandescent lamps, passing traps, portals, mechanical mail boxes and other quests will show you the way to the end of the level. All the action takes place in the setting of the harsh communist future dominated by bulky analog electronics.' FROM games WHERE igdb_id = 155872 ON CONFLICT (game_id, language_code) DO NOTHING;
