INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silicon Dreams', 'Welcome, interrogator, to the year 2065. You were constructed to question other, disobedient androids: why do they glitch? Why do they believe they have free will? Manipulate their emotions; extract their secrets; scrap those beyond repair. You wouldn''t disobey your creators, would you?' FROM games WHERE igdb_id = 132497 ON CONFLICT (game_id, language_code) DO NOTHING;
