INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saints and Sinners', 'With Saints and Sinners give a life to Sinner in Dark Medieval Era or join the Saints to find Sinner among them and execute him front of others. With your 4-8 friends or other players use in-game chat or voice chat to find who is Sinner or prove that you are not a Sinner! In this multiplayer thriller themed game all lies and slanders are free.' FROM games WHERE igdb_id = 142799 ON CONFLICT (game_id, language_code) DO NOTHING;
