INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'After the Fall', 'From the creators of the hit VR shooter Arizona Sunshine comes an epic multiplayer VR action FPS with seamless, co-operative gameplay at its core that pits up to four players against a vast, hostile VR world in a raging fight for survival. Set in the ice-covered ruins of LA nearly 20 years after the apocalypse, After the Fall combines a living, breathing VR world shared with players from all over the world, a cinematic and atmospheric campaign, action-packed solo and multiplayer gameplay, and endgame built from the ground up for VR.' FROM games WHERE igdb_id = 119330 ON CONFLICT (game_id, language_code) DO NOTHING;
