INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hextech Mayhem: A League of Legends Story', 'Hextech Mayhem: A League of Legends Story is a fast-paced rhythm runner where every action has an explosive reaction and no amount of mayhem is too much, featuring familiar champions from the League of Legends universe. Take on the role of Hexplosives expert Ziggs as you rampage through the neighborhoods of Piltover while you bomb, bounce, and bop to the beat of the music to avoid obstacles, disarm enemies, and light fuses. Use the Freestyle Mayhem System to create spontaneous blasts and grab bonus points… all while dodging the fun police and showing them what they’re really missing.' FROM games WHERE igdb_id = 180299 ON CONFLICT (game_id, language_code) DO NOTHING;
