INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('slipways', 141412, '2021-06-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lgz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru3i.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slipways', 'Turn desolate planets into a vast trade empire. Hatch plans. Research game-breaking technologies. Still be done in time for lunch. Enjoy the endless possibilities of a space grand strategy game in 60 minutes flat. Slipways takes the space grand strategy genre and condenses the best parts of it down by throwing away all the micromanagement and the steep learning curve. The result is a game in which you can finish a run quickly, but still have a deep experience full of important decisions. Forget about tedious micromanagement and spending time waiting for ships to build. In Slipways, every action you take has immediate consequences, and every choice you make is of paramount importance. Your planets govern themselves while you focus on making the right decisions to get them what they need. You''ll waste none of your precious time on busywork - a single run takes 40-60 minutes and they are all filled with the good stuff.' FROM games WHERE igdb_id = 141412 ON CONFLICT (game_id, language_code) DO NOTHING;
