INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('impulse--1', 137027, '2021-12-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gxw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scky0h.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Impulse', 'A free-to-play, play-to-earn first-person multiplayer shooter by Ascendance Games. Play Impulse completely free by joining our training arenas where you can earn Common Credits just by getting eliminations to buy NFTs with real world value that you can trade or sell. Amp it up a bit by joining the Ascendance Credit arenas, where you can earn real money for every kill! Join Deathmatch in a one versus all brawl, or play in a Teams mode to go up against another group of players in an all-or-nothing showdown. Earn DNA points as you play to fully customize your characters the way you want with our robust character creator. Start off by playing as a metallic Synth, to branch off and become a Human, Cyborg, Alien, or more! You can adjust your character to be a large brute that can take more damage, or be smaller and nimble but make sure not to get hit!' FROM games WHERE igdb_id = 137027 ON CONFLICT (game_id, language_code) DO NOTHING;
