INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mutropolis', 'A lovely SCI-FI archaeological post-apocalyptic adventure.  In the 50th century, the great humankind achievements, such as pyramids or Humphrey Bogart’s movies, were completely forgotten.  Henry and his nerdy team of archaeologists have been working hard for years, on the ground, digging treasures with the extremely rare hallmark “Made in China” and watching weird Indiana Jones documentaries.  Until some dog-looking God came to ruin everything.' FROM games WHERE igdb_id = 115821 ON CONFLICT (game_id, language_code) DO NOTHING;
