INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ALTF4', 'ALTF4 is a 3rd person permadeath runner game where you play a clumsy knight who needs to overcome multiple traps in order to reach his goal. But the way to his destination won''t be simple. There are no saves in this game, traps are constantly trying to kill you and character movements are filled with challenges. Do you have what it takes to clear the game in one go?' FROM games WHERE igdb_id = 143759 ON CONFLICT (game_id, language_code) DO NOTHING;
