INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blub Emporium', 'Blub Emporium is a dense isometric shop manager that gives you access to the entire production chain. Gather resources from the wilderness then build factories to produce the things you sell. Collect tonnes of unique items, decorate everything, complete puzzles, and so much more!' FROM games WHERE igdb_id = 158418 ON CONFLICT (game_id, language_code) DO NOTHING;
