INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dadish 2', 'He’s a dad, and a radish, and he’s back in his biggest adventure yet! After an impromptu “Bring Your Kids To Work Day” goes awry, Dadish sets off to find his missing children. Along the way he’ll wade through swamps, ride rockets, climb a big tree, and even visit outer space! Help reunite Dadish with his missing kids in this charming and challenging platforming adventure.' FROM games WHERE igdb_id = 142986 ON CONFLICT (game_id, language_code) DO NOTHING;
