INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dominion', 'This is a game of building a deck of cards. The deck contains your resources, victory points, and the things you can do. It starts out a small collection of Estates and Coppers, but you hope that by the end of the game it will be brimming with Gold, Provinces, and the inhabitants of your kingdom.' FROM games WHERE igdb_id = 164217 ON CONFLICT (game_id, language_code) DO NOTHING;
