INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('marsupilami-hoobadventure', 150008, '2021-10-06', 84, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co31am.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arfxb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marsupilami: Hoobadventure', 'Discover with Marsupilami: Hoobadventure, a brand new adventure inviting young players and adult alike to take control of the three Marsupilamis from the Palombian forsest. Punch, Twister and Hope are three Marsupilamis living a peaceful life in Palombia. Their lives are about to take a drastic turn when they accidentally open a sarcophagus whilst playing with debris on a beach, releasing a mysterious ghost cursing all the animals! Thankfully, our three Marsupilamis are immune to the curse and decide to set out on an adventure and find the ghost and reverse the curse. Inspired by the comic book Marsupilami from Franquin, this 2.5D platformer will take you on a colorful journey through the Palombian jungle, a coastal city and even an abandoned temple. Jump, punch, dash and swing with your tail like only Marsupilamis do!' FROM games WHERE igdb_id = 150008 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 150008 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
