INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Man Remastered', 'He is coming, stalking criminals in the spirit world and the real world. A possessed man is coming, a voodoo mask in his chest and lines of power in his back. Shadow Man is coming, trailing evil from Liveside to Deadside. To stop an apocalypse. To save your soul. Shadow Man Remastered upgrades the visuals and effects with a 4K widescreen presentation, and implements the studio''s "KEX" engine - previously used to create the remasters of System Shock, Turok 2, and Forsaken.' FROM games WHERE igdb_id = 131889 ON CONFLICT (game_id, language_code) DO NOTHING;
