INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lamentum', 'Lamentum is a pixel art survival-horror game set in New England in the mid-nineteenth century. To solve the dark secret at the heart of Grau Hill Mansion, you will have to immerse yourself in a nightmare world full of terrible creatures. Choose well in whom to trust, every decision you make may alter the course of the story. Will you survive?' FROM games WHERE igdb_id = 115588 ON CONFLICT (game_id, language_code) DO NOTHING;
