INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Weapon of Choice DX', 'Weapon of Choice DX is a high-energy, run ''n'' gun where each playable character is unique with their own special weapon and abilities! Blast insane aliens, find new player characters, and choose between branching paths! The world is being taken over by gene-combining beings from beyond the stars! Hideous new creatures are popping up everywhere, and it''s up to the Solus Operatives to grab their unique weapons and split some disgusting alien skulls!' FROM games WHERE igdb_id = 154991 ON CONFLICT (game_id, language_code) DO NOTHING;
