INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Green Phoenix', 'Green Phoenix is an on-rails 3D space shooter mixed with a deep narrative experience that focuses on the concept of ego and the meaning of freedom. In Green Phoenix, we are transported to a single player story where society is fully technologized and authoritarian and take us on the role of the spaceship AI, Green Phoenix, as it remembers its dead pilot, Dana, and embarks on a journey of revenge.' FROM games WHERE igdb_id = 148095 ON CONFLICT (game_id, language_code) DO NOTHING;
