INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('killsquad', 118600, '2021-10-21', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ssm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arsjx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Killsquad', 'Hack and slash? Check. Twin-stick-shooter? Check. 4 player coop to slay hordes of aliens & bosses with your friends? Check. Skills, upgrades, weapons, gears, talismans and more to make you stronger? Check. Wake up, bounty hunter. We have a mission for you. Time to clean up the scum of the galaxy. Welcome to Killsquad: a co-op action game that blends twin-stick shooter, hack and slash and drops in a dash of character customization & progression. Join us on a journey to five planets full to the brim with enemies for you to annihilate. Choose your hero, select your skills, weapons, gears and talismans, and unleash hell through waves of relentless enemies and fearsome bosses.' FROM games WHERE igdb_id = 118600 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 118600 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 118600 AND ge.slug = 'hack-and-slash-beat-em-up' ON CONFLICT DO NOTHING;
