INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eastward', 'Eastward is a beautifully detailed and charming adventure RPG, from Shanghai-based indie developers, Pixpil and published by Chucklefish. Escape the tyrannical clutches of a subterranean society and join Eastward’s unlikely duo on an exciting adventure to the land above! Discover beautiful yet bizarre settlements and make new friends as you travel across the world by rail. Inspired by 90s Japanese animation, the visual style of Eastward has been brought to life using a combination of a modern, innovative 3D lighting system and a rich retro-pixel artwork.' FROM games WHERE igdb_id = 24417 ON CONFLICT (game_id, language_code) DO NOTHING;
