INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Melty Blood: Type Lumina', '"MELTY BLOOD" is a series of 2D fighting games based on TYPE-MOON''s visual romance novel "Tsukihime". Since the game''s original release on PC in 2002, it has also had a number of ports for arcade, PlayStation 2, and Steam. Now, at long last, the "MELTY BLOOD" series is making its way to PlayStation4, Nintendo Switch, Xbox One, and Steam on September 30, 2021 in the form of "MELTY BLOOD: TYPE LUMINA".' FROM games WHERE igdb_id = 145017 ON CONFLICT (game_id, language_code) DO NOTHING;
