INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cards & Tankards', 'Grab some ale, choose your deck, and get ready for Cards & Tankards - the laid-back strategy card game that is truly immersive and easy to learn. Join a tavern for a shared virtual experience where you can battle other online players, or just hang out while you build your deck, sip your tankard, and socialize in our cozy fantasy tavern!' FROM games WHERE igdb_id = 143354 ON CONFLICT (game_id, language_code) DO NOTHING;
