INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nier-re-in-carnation', 132005, '2021-02-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7bm4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7gr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NieR Re[in]carnation', 'NieR Re[in]carnation is a role-playing video game which takes place in the universe of NieR and its sequel, NieR: Automata. Set in a realm called the Cage, the player takes on the role of a girl guided by a ghost-like being. The gameplay is split into three parts: exploration, where players can roam the different stages of the Cage; weapon stories, which showcase memories from different characters in a side-scrolling painting-like perspective; and battles, featuring a mix of real-time combat with time-based skills. Players will have to assemble teams of 3 characters while taking into account their elements, roles and equipment in order to prevail in PvE and PvP encounters.' FROM games WHERE igdb_id = 132005 ON CONFLICT (game_id, language_code) DO NOTHING;
