INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wavetale', 165309, '2021-11-10', 78, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7wdy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4df0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wavetale', 'Wavetale is a story driven, third-person action-adventure platformer, set in an island world built atop the remains of a once magnificent city. Player takes on the role of Sigrid, a headstrong girl who gains the ability to run on water through the help of a mysterious shadow. Wavetale offers a tight-knit story combined with a charming art style and delightful soundtrack and invites players to explore its world through its fast-flowing gameplay, where traditional platforming elements meet a unique surfing experience on a dynamic ocean. The intuitive controls make Wavetale accessible and family friendly, while at the same time encouraging mastery as the player will need to understand the full range of movement. Guide Sigrid through the archipelago as the calamity that once sunk the city once again looms on the horizon.' FROM games WHERE igdb_id = 165309 ON CONFLICT (game_id, language_code) DO NOTHING;
