INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pulsar-lost-colony', 16687, '2021-06-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3c8y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ardhc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pulsar: Lost Colony', 'Team up to operate an advanced starship and explore a randomized galaxy falling into chaos. Each player assumes a role aboard the ship: Captain, Pilot, Scientist, Weapons Specialist and Engineer. Coordination between your crewmembers will be essential in order to survive the perils that await you. Control the various stations that run your ship. Reroute power between ship systems, scan alien planets for lifeforms, run powerful programs to change the tide of battle, or start up the warp drive to escape a conflict you cannot win. The strategies you use are up to you—or your Captain. Embark on missions, investigate abandoned stations, and scavenge for components that could aid you in your voyage. Teleport down to the surfaces of alien planets, where you may face extreme environments and dangerous creatures. Trek across the galaxy, and discover what lies on its fringes.' FROM games WHERE igdb_id = 16687 ON CONFLICT (game_id, language_code) DO NOTHING;
