INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('oceans-heart', 142340, '2021-01-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2o7o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcp2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ocean''s Heart', 'Ocean’s Heart is an action RPG featuring detailed pixel art with a heavy focus on exploration. In a lively world teeming with secrets and mysteries, Tilia sets out in search of her missing father. Follow the trail through the ruins of a flooded kingdom, shape the future of the current world, or keep your head down and focus on your own mission in this epic retro-inspired adventure! Explore a detailed and beautiful world, brimming with secrets hidden in misty forests, isolated mountain peaks, or saltwater marshes. Every area is filled with unique and meaningful sidequests, ancient mysteries, and dangers. Battle fearsome monsters and wield various weapons and ancient magic to defeat or outmaneuver them. Search for special materials to upgrade your weapons until you''re demolishing monsters who once put up a fierce fight. Gather various items throughout the world to craft potions, upgrade weapons, and expand your ever-growing arsenal.' FROM games WHERE igdb_id = 142340 ON CONFLICT (game_id, language_code) DO NOTHING;
