INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grapple Hoops', 'Dunk on your opponents in a fast-paced first person action game with basketball, grappling hooks, parkour and explosions! FAST-PACED AND AGGRESSIVE COMBAT Outmaneuver opponents as you wall run and slide behind them leaving them paralyzed after a devastating blow with a basketball to the head. Outmaneuver opponents as you wall run and slide behind them leaving them paralyzed after a devastating blow with a basketball to the head. FAST AND FLUID GAMEPLAY Grapple and swing around like crazy, kick doors and windows, run horizontally on any wall, slide under obstacles and use jump pads to launch yourself up in the air and hit top speed quickly.' FROM games WHERE igdb_id = 142529 ON CONFLICT (game_id, language_code) DO NOTHING;
