INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Just Act Natural', 'An asymmetric online multiplayer party game where one group of players hide among a crowd of NPCs doing various tasks while other players seek them out from above. The game features a hand-sculpted clay art style using hundreds of clay models that are scanned and imported virtually.' FROM games WHERE igdb_id = 148161 ON CONFLICT (game_id, language_code) DO NOTHING;
