INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cris Tales', 'Discover a unique combination of branching stories, innovative combat, and classic RPG gameplay in Cris Tales’ exciting and unforgettable exploration of how our actions echo through time. Join the newly awakened Time Mage, Crisbell, and her fantastical companions in a fantasy world facing a grim future. The powerful Time Empress and her forces threaten to bring about a cataclysm tearing apart Crystallis and the other four Kingdoms of the region.' FROM games WHERE igdb_id = 119349 ON CONFLICT (game_id, language_code) DO NOTHING;
