INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Tonight', 'A narrative puzzle game about two people trying to find their way back together in a city on fire. Maya sets out to find her way across the city by car, train, roller skate and rooftop all while avoiding police barricades, traffic jams and the spreading fire. Confined to his small apartment, Devin anxiously awaits Maya''s arrival. He reminisces about their time together as he looks at all the mementos scattered around his place. Will Maya and Devin be able to find each other before the city is engulfed in flames?' FROM games WHERE igdb_id = 139461 ON CONFLICT (game_id, language_code) DO NOTHING;
