INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('warhammer-age-of-sigmar-storm-ground', 137328, '2021-05-26', 59, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2t6w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7pe.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warhammer Age of Sigmar: Storm Ground', 'Become the commander of one of the extraordinary factions of Warhammer Age of Sigmar - a dark-fantasy universe where immortal knights ride heavenly stardrakes to eradicate Death across a multitude of realms. This is Storm Ground, a world of legends, heroes, hellish creatures and fearsome battles. Lead your highly-customisable force in this dynamic and spectacular skirmish turn-based strategy game packed with fast-paced warfare. Victories allow you to collect and upgrade new types of units, powerful equipment, and unlock devastating skills. Explore all the routes in Storm Ground''s non-linear campaign. During each new playthrough, overcome new odds to find unique units and gears. Build your legendary army and defy other players in epic online duels.' FROM games WHERE igdb_id = 137328 ON CONFLICT (game_id, language_code) DO NOTHING;
