INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('metro-exodus-enhanced-edition', 143292, '2021-05-06', 92, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coab4r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1do5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metro Exodus: Enhanced Edition', 'Metro Exodus is an epic, story-driven first person shooter from 4A Games that blends deadly combat and stealth with exploration and survival horror in one of the most immersive game worlds ever created. Explore the Russian wilderness across vast, non-linear levels and follow a thrilling story-line that spans an entire year through spring, summer and autumn to the depths of nuclear winter. Inspired by the novels of Dmitry Glukhovsky, Metro Exodus continues Artyom’s story in the greatest Metro adventure yet. Enhanced Edition offers additional Ray Tracing features including Advanced Ray Traced Reflections and support for DLSS 2.0. Additionally, this update improves its existing Ray Traced Global Illumination tech to make every light source fully Ray Traced. It also implements the Ray Traced Emissive Lighting tech from The Two Colonels throughout the game.' FROM games WHERE igdb_id = 143292 ON CONFLICT (game_id, language_code) DO NOTHING;
