INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Animal Royale', 'Select your favorite adorably murderous fox, panda, or sloth and parachute into a furocious 64-player battle arena. Explore a top-down 2D world, full of exotic biomes, psychotic animals, hamster balls, emus and much more. Wield pistols, snipers, miniguns, explosives, and silly dances on your way to the top of the food chain.' FROM games WHERE igdb_id = 109826 ON CONFLICT (game_id, language_code) DO NOTHING;
