INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Odin: Valhalla Rising', 'ODIN: Valhalla Rising is an RPG game rooted in Nordic mythology, developed by Lionheart Studio and published by the South Korean company Kakao Games. The game is available on PC, Android, and iOS. After its initial release in South Korea in 2021, ODIN: Valhalla Rising was launched globally in April 2025, reaching players in the US, Europe, and Asia.' FROM games WHERE igdb_id = 137939 ON CONFLICT (game_id, language_code) DO NOTHING;
