INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Artist Life Simulator', 'Live the life of (a starving) artist in 19th century alternative history. Collect and combine feelings, memories, ideas and inspirations, fight with depression, addiction or madness and other mental phenomenon. Paint masterpieces, sell them for riches (or scraps) and explore the city of Nova Oportunia. A unique card-based roguelite with 18 alternative endings.' FROM games WHERE igdb_id = 154076 ON CONFLICT (game_id, language_code) DO NOTHING;
