INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unexplored 2: The Wayfarer''s Legacy', 'Unexplored 2: The Wayfarer''s Legacy is a roguelite action-RPG and prodigious sequel to the critically acclaimed indie gem, Unexplored. Leave the Dungeon of Doom behind and venture into a vast, wondrous world as you embark on a heroic quest to destroy the mysterious Staff of Yendor.' FROM games WHERE igdb_id = 119343 ON CONFLICT (game_id, language_code) DO NOTHING;
