INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('chicken-invaders-universe', 144460, '2021-04-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2uti.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arduo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chicken Invaders Universe', 'Chicken Invaders needs no introduction. Well, fine, if you insist. Chicken Invaders is the most successful chicken game of this millennium (not to mention the previous one). The game puts you at the forefront of a battle against invading intergalactic chickens, bent on revenge against the human race for our oppression of Earth chickens. In Chicken Invaders Universe, you assume the role of a new recruit in the United Hero Force (UHF), mankind''s last hope against the fowl Henpire. You start your UHF career deployed in some backwater galactic star system, and it''s up to you to advance through UHF ranks and earn your place in the honorary annals of Heroes Academy. Travel across the galaxy, explore strange new worlds, seek out new life and new civilizations, and exterminate any Henpire forces that cross your path. And do so in style.' FROM games WHERE igdb_id = 144460 ON CONFLICT (game_id, language_code) DO NOTHING;
