INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('insurmountable', 133846, '2021-04-29', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2fhl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar786.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Insurmountable', 'Insurmountable is a strategic adventure game with roguelike elements, in which you have to overcome a dangerous randomly generated mountain. Confront the differing terrains as a lonely mountaineer and make your way through Ice, Snow and Stone. Use items to keep up your steadily sinking stats, while making your way up and down the insurmountable heights. The dynamic and ever-changing weather system, the day-night cycles, and numerous other events will make sure that you meet tough challenges on your journey to the top. To live up to these challenges, you are able to improve your character. By earning experience points through events, you can choose skills to help you with certain playstyles. One of the serveral roguelike elements is permadeath, which forces you to try various strategies in your pursuit to summit the mountain. The game focuses, on the one hand, on the decisions you make in a risky environment full of uncertainties, on the other hand, on evoking intense emotions people experience in such a harsh and savage environment.' FROM games WHERE igdb_id = 133846 ON CONFLICT (game_id, language_code) DO NOTHING;
