INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jigsaw-pieces-2-shades-of-mood', 144535, '2021-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2uxz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arwne.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jigsaw Pieces 2: Shades of Mood', 'Making jigsaw puzzles makes you happy! Making jigsaw puzzles is a popular way to relax. Forming a harmonious whole of all loose puzzle pieces makes you forget about everyday stress. To make sure that even the last bit of stress will disappear, all puzzles in this beautiful game consist of comforting and uplifting images. Surround yourself with bright sunshine, warmth and inspiration and just feel happy! Since you make these jigsaw puzzles on your computer, you won’t be distracted by lack of space. Now nothing stands in the way of a relaxed feeling! Features - 7 Chapters + the Secret One - Increase the size of a puzzle up to 1000 pieces - Different cut-out patterns+ Mosaic and Lacy cut-outs - 16 intriguing game modes - Customizable difficulty: from relaxing to challenging - Customizable Brightness and Colouring - HD quality levels - Great rewards every day - New Hint System - Interesting Random Puzzles of the day - Relaxing soundtrack - Set your most beloved levels as HD desktop wallpapers' FROM games WHERE igdb_id = 144535 ON CONFLICT (game_id, language_code) DO NOTHING;
