INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cloud-gardens', 136407, '2021-09-01', 79, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2swb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar11lg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cloud Gardens', 'A chill game about using plants to overgrow abandoned wasteland dioramas. In Cloud Gardens players must harness the power of nature to overgrow lo-fi scenes of urban decay and manufactured landscapes. By planting seeds in the right places, they’re able to create small overgrown dioramas of brutalism and beauty, salvaging and repurposing hundreds of discarded objects to create unique structures for nature to reclaim. Players can dive into a relaxing sandbox mode with no goals, where they are simply left to delight in their own creativity and create beautiful scenes, or take on a “campaign” of six chapters, where the task is to strike a balance between nature and the manufactured by covering each scene with salvaged objects and lush vegetation. This is a chill game where the player is allowed to delight in their own creativity. The player''s task is to completely cover the scene in plants. As you overgrow the objects, a meter fills to show your progress. You are given objects to expand the scene. These objects contribute energy to the growing of plants, but you will also have to cover them in foliage to complete the stage, striking a balance between nature and the manufactured. With generative soundscapes by Amos Roddy, composer of the Kingdom Series.' FROM games WHERE igdb_id = 136407 ON CONFLICT (game_id, language_code) DO NOTHING;
