INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('carestia', 136143, '2021-05-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2e4h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar59wg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carestia', 'Carestia Human kind has discovered a very rare crystal capable of providing huge amounts of power. With a lot of advancements in technology, daily life was surrounded with helpful robots and inventions. One day, unfortunately, all those technology became self-aware and decided that the human kind was not well fitted for Earth. Some people escaped to an artificial planet, where they live their lives dreaming of one day going back to Earth. You have been born on that artificial planet and trained from your very first days until now to overcome any problems you may face. You are a soldier of the New Day. A special force assembled to take Earth back. Now it''s time to put all that training into test. Your grand master demands your assistance into entering an underground fortress and stealing one of that power crystals. That will leave the fortress in a vulnerable state, making way to further reinforcements to establish a base of operation on Earth. Gameplay Carestia is a mix of intriguing puzzles and precise action battles into a 2D side scrolling platformer. You will go from moments of thinking to solve and overcome the puzzles to moments of fast reactions to defeat a boss. The puzzles uses an energy mechanism that will make you use the right items to wire everything in order to proceed.' FROM games WHERE igdb_id = 136143 ON CONFLICT (game_id, language_code) DO NOTHING;
