INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Bore', 'Project bore is a Psychological-Horror RPG is about the story of a man trying to fight himself and his inner demons. Project Bore takes you through seven handcrafted levels with their own tailor-made songs. Project Bore was made as a sort of experiment on how a new approach on the traditional turn-based could lead to a different yet exciting experience.' FROM games WHERE igdb_id = 185784 ON CONFLICT (game_id, language_code) DO NOTHING;
