INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stack Up (or dive trying)', 'Stack Up! (or dive trying) is an endless platformer where the main quest is to climb the leaderboard to reach the top. The theme is simple, objects will fall from above and the player needs to pick it up to reach the Heightscore, but it''s importants to avoid the water, if it takes the player it''s game over and need to start again. Some object will help to climb faster but others will bring to the endgame as soon as they can, so it''s up to the player.' FROM games WHERE igdb_id = 133132 ON CONFLICT (game_id, language_code) DO NOTHING;
