INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Square vs Triangles', 'Square Vs Triangles is a fast-action shooter game where your objective is to defeat all the triangles and bosses of each level. There are multiple types of bosses and enemies that you can defeat one by one or use your special abilities and kill more than one at once. Quick reflexes, intelligence and a winner mindset can make you the one to save the squares!' FROM games WHERE igdb_id = 164739 ON CONFLICT (game_id, language_code) DO NOTHING;
