INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sixit', 'Sixit is a small narrative puzzle game where you have SIX actions per run. In Sixit, you start each run by choosing the order of your six actions, which will be used to solve puzzles and explore the forest. Over the course of multiple runs you will unlock new abilities, meet cute animal friends, and (hopefully) save the village from the impending storm.' FROM games WHERE igdb_id = 145992 ON CONFLICT (game_id, language_code) DO NOTHING;
