INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tedd''or', 'Fantasy action-adventure RPG with an open world and diverse enemies. Including a complex upgrade system and a lootbox-style way of obtaining new abilities. The game contains a simple story you can follow to reveal secrets of the world you play in. Multiple dungeons with juicy rewards you can obtain by putting your skills to the test. The game also contains a competitive mode where you must defeat waves of enemies as fast as possible.' FROM games WHERE igdb_id = 195088 ON CONFLICT (game_id, language_code) DO NOTHING;
