INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teleport Tower', 'Teleport Tower is a "Foddian" platformer where you navigate the map with a portal gun. It was created in 10 days as a submission for Ludwig Jam. It was made with plain old Typescript and HTML, using no preexisting game engine. Follow Dahlia''s journey to recover her missing gem from her portal gun, so she can find her way back home.' FROM games WHERE igdb_id = 179756 ON CONFLICT (game_id, language_code) DO NOTHING;
