INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Far Cry VR', 'Crystal clear water sparkles as far as the eye can see. Bright, silky sand sifting between your toes. Good friends, great times and not a care in the world. So many memories in the making, and even more selfies! That’s exactly how this trip was going before your group was captured and imprisoned by Vaas, and his small army of henchmen. Not quite the tropical holiday you were hoping for?' FROM games WHERE igdb_id = 138767 ON CONFLICT (game_id, language_code) DO NOTHING;
