INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cowardly Heroes', 'An Alien invasion has arrived and these heroes are doing what they do best: running! Help them dodge and avoid the many incoming obstacles and enemies in this offline arcade game. Start a fun and challenging run. Collect coins to increase your score and unlock new heroes and bonuses, grab random risky powerups, dodge and overcome enemies, and progress to new challenging levels! Deadly lasers, threatening skeletons, angry minotaurs, fragile barrels, and many more creative obstacles are waiting to ruin your high score!' FROM games WHERE igdb_id = 182298 ON CONFLICT (game_id, language_code) DO NOTHING;
