INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pikmin Bloom', 'Grow your Pikmin, make flowers bloom, and keep track of your precious memories, all through the simple act of walking. Whether you’re going for a short walk around the corner or commuting to work, today’s the very first day of the rest of your Pikmin adventures! Gather your squad and embark on a journey of rediscovery where every step counts.' FROM games WHERE igdb_id = 178290 ON CONFLICT (game_id, language_code) DO NOTHING;
