INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('piczle-puzzle-and-watch-collection', 154906, '2021-07-29', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ggd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvea.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Piczle Puzzle & Watch Collection', 'This is the Piczle Puzzle & Watch Collection, a love-letter to the days of LCD handheld gaming! Play one of three logic-puzzles designed to look like those pioneering handheld gaming devices of yore. Piczle Cross Choose from over 200 10x10 nonograms to play. Game A requires you to clear them making fewer than 3 mistakes. Game B let''s you puzzle as you please. Your fastest time for each puzzle is recorded. Piczle Pattern Turn every square in a grid black following a cross pattern. Start with a blank slate and record your fewest moves, or start from a randomly generated grid. Piczle Loops 72 logic-puzzles that require you to draw an uninterrupted looping line on a grid following the clues. Game A offers 36 puzzles from easy to moderatem, Game B another 36 from moderate to hard. Lovingly unbox your games. Take a close look at every nook and cranny of the devices, the packaging and the included materials. Read the manual, like in the good old days! Don''t press on the glass, it might damage the liquid crystal! Use the controllers or press the buttons using touch-screen. The Piczle Puzzle & Watch Collection provides a nostalgic experience and hours of logic-puzzling fun.' FROM games WHERE igdb_id = 154906 ON CONFLICT (game_id, language_code) DO NOTHING;
