INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('poker-squadrons-battle-of-britain', 143917, '2021-04-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ty3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arw7b.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Poker Squadrons: Battle of Britain', 'Fight the Battle of Britain, four Poker hands at a time! Poker Squadrons is a single-player card game where you play out the events of the Battle of Britain. You take control of a British Royal Air Force Fighter Squadron and are pitted against a computer opponent controlling the German Luftwaffe. Both sides draw cards from a shared 52-card deck to simultaneously assemble 4 poker hands to send into combat. The shuffled deck and opponent''s AI ensure a unique challenge each time you play. Poker Squadrons brings you back to 1940, when Germany launched Operation Sea Lion, their plan to invade Great Britain. Events from the historic aerial battle are presented in the game''s 18 stages, which are played in 4 phases: 1. Scramble: Draw cards to assemble the best 4 poker hands possible. 2. Secret Cards: Play a secret card increase your chance of victory in combat. NOTE: This phase is not available until stage 3. 3. Form Up: Drag to reorder your assembled poker hands to match up against the incoming poker hands, some of which may contain hidden cards that remain face-down until the combat phase begins. 4. Combat: You must win at least 3 out of the 4 poker hand matchups to clear each stage.' FROM games WHERE igdb_id = 143917 ON CONFLICT (game_id, language_code) DO NOTHING;
