INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of the Black Death', 'Tales of the Black Death is a choice driven interactive fiction plague survival story that pins your morality against your survival. The game is a three-part series set in the Middle Ages during the plague that spread from Italy to France and finally reached England. In Tales of the Black Death, you play as Baldasar, a young Italian boy.' FROM games WHERE igdb_id = 178068 ON CONFLICT (game_id, language_code) DO NOTHING;
