INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadowgate VR: The Mines of Mythrok', 'The first book in the Shadowgate Saga, Shadowgate VR: The Mines of Mythrok brings the hit adventure series to virtual reality! Step into the fantasy world of Kal Torlin like never before and immerse yourself in this exciting action/adventure game made exclusively for the Oculus Quest! With Odin the raven as your guide, and three difficulty levels to fit your play style, it''s time to discover what secrets await within the Mines of Mythrok!' FROM games WHERE igdb_id = 186959 ON CONFLICT (game_id, language_code) DO NOTHING;
