INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jett: The Far Shore', 'Jett: The Far Shore invites you on an interstellar expedition to carve out a future for a people haunted by oblivion in this cinematic action adventure. As scout Mei, be the first to deploy to a mythic ocean planet, take the helm of a ''jett'' and explore a vast unknown - skim low over waves, roar up pristine coastlines and carve through otherworldly woods. Adapt to an intricate, systemic open world and persevere through adversity alongside an intimate ensemble in this heartfelt story of courage, wonder and regret.' FROM games WHERE igdb_id = 134591 ON CONFLICT (game_id, language_code) DO NOTHING;
