INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA 2K22', 'NBA 2K22 puts the entire basketball universe in your hands. Play now in real NBA and WNBA environments against authentic teams and players. Build your own dream team in MyTeam with today’s stars and yesterday’s legends. Live out your own pro journey in MyCareer and experience your personal rise to the NBA. Flex your management skills as a powerful Executive in MyGM and MyLeague. Anyone, anywhere can hoop in NBA 2K22.' FROM games WHERE igdb_id = 157446 ON CONFLICT (game_id, language_code) DO NOTHING;
