INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fatal Frame: Maiden of Black Water', 'Experience all of the horror from the original FATAL FRAME: Maiden of Black Water with new remastered visuals, new costumes and photo mode features. The main adventure consists of three interconnected stories which lead the player to uncover the horrifying truth behind a string of recent tragic deaths taking place in a forest with an infamous history. Take on the role of one of three people with the power of the Camera Obscura and the ability to see the shadows of those spirited away. The story will take you on a frightening adventure through the ruins of an eerie inn, a shrine filled with life-size dolls, and a lake full of dead priestesses.' FROM games WHERE igdb_id = 152397 ON CONFLICT (game_id, language_code) DO NOTHING;
