INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aeon Drive', 'Aeon Drive is an action platformer game set in a cyberpunk version of Barcelona. The player controls Jack, a stranded space pilot on a quest to retrieve faulty pieces of dimension-bending machinery in order to preserve the space-time fabric of the universe. Jack will have to overcome a myriad obstacles using her sword, her teleportation dagger, and her unique skill to control time.' FROM games WHERE igdb_id = 135410 ON CONFLICT (game_id, language_code) DO NOTHING;
