INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Omno', 'A single-player journey of discovery through an ancient world of wonders. Full of puzzles, secrets and obstacles to overcome, where the power of a lost civilization will carry you through forests, deserts and tundras - even to the clouds. Besides offering an interactive world, Omno challenges you with puzzles, hidden secrets and obstacles to overcome in 3D puzzle platformer style.' FROM games WHERE igdb_id = 111661 ON CONFLICT (game_id, language_code) DO NOTHING;
