INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Host 714', 'In Host 714, you are going to live as Squid, a drug addicted hobo who was invited by a governmental organization, the Orange Institute, to join a drug addiction rehab center with experimental treatment and social reintegration. Arriving at the Institute on a faraway island, Squid realizes that the proposal was not what they claimed to be. Now you are a test subject, with an uncertain fate. Help our protagonist escape from the Orange Institute in this challenging stealth game!' FROM games WHERE igdb_id = 153440 ON CONFLICT (game_id, language_code) DO NOTHING;
